    { const char * tb_v2210 = "// ядро процессора («звезда»): его номер, кого он сейчас ведёт, свой стек для пустого хода.\n"; *(const char * *)tb_grow(v_lines) = tb_v2210; }
    { const char * tb_v2211 = "// Регистр GS у каждого ядра смотрит на его запись (в самом начале — адрес её самой)\n"; *(const char * *)tb_grow(v_lines) = tb_v2211; }
    { const char * tb_v2212 = "#define TB_NCPU 16\n"; *(const char * *)tb_grow(v_lines) = tb_v2212; }
