    { const char * tb_v2222 = "TB_API int tb_ncpu = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2222; }
    { const char * tb_v2223 = "TB_INL tb_cpu *tb_me(void) { tb_cpu *c; __asm__ volatile(\"movq %%gs:0, %0\" : \"=r\"(c)); return c; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2223; }
    { const char * tb_v2224 = "// короткое дело библиотеки (память, экран, список задач): прерывания выключены и взят общий\n"; *(const char * *)tb_grow(v_lines) = tb_v2224; }
    { const char * tb_v2225 = "// замок — так его не делят ни прерывание, ни другое ядро процессора. Можно вкладывать\n"; *(const char * *)tb_grow(v_lines) = tb_v2225; }
    { const char * tb_v2226 = "TB_API volatile int tb_bkl = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2226; }
