    { const char * tb_v2729 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v2729; }
    { const char * tb_v2730 = "// адреса из раскладки ядра (компоновщик): где код, где кончается нижняя память, где куча\n"; *(const char * *)tb_grow(v_lines) = tb_v2730; }
    { const char * tb_v2731 = "extern char tb_code_start[], tb_code_end[], tb_tls_start[], tb_tls_end[], tb_heap_area[], tb_kernel_end[];\n"; *(const char * *)tb_grow(v_lines) = tb_v2731; }
    { const char * tb_v2732 = "TB_API unsigned char tb_stack[1 << 20] __attribute__((aligned(4096), used));\n"; *(const char * *)tb_grow(v_lines) = tb_v2732; }
