    { const char * tb_v2734 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v2734; }
    { const char * tb_v2735 = "// авария ядра: красным на экран и в порт, потом стоп\n"; *(const char * *)tb_grow(v_lines) = tb_v2735; }
    { const char * tb_v2736 = "__attribute__((noreturn)) static void tb_panic(const char *what, uint64_t a, uint64_t b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2736; }
    { const char * tb_v2737 = "    __asm__ volatile(\"cli\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2737; }
    { const char * tb_v2738 = "    char buf[160];\n"; *(const char * *)tb_grow(v_lines) = tb_v2738; }
    { const char * tb_v2739 = "    snprintf(buf, sizeof buf, \"\\n*** ядро остановлено: %s (0x%llx, 0x%llx)\\n\", what, (unsigned long long)a, (unsigned long long)b);\n"; *(const char * *)tb_grow(v_lines) = tb_v2739; }
    { const char * tb_v2740 = "    fputs(buf, stderr);\n"; *(const char * *)tb_grow(v_lines) = tb_v2740; }
    { const char * tb_v2741 = "    exit(3);\n"; *(const char * *)tb_grow(v_lines) = tb_v2741; }
    { const char * tb_v2742 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2742; }
    { const char * tb_v2743 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v2743; }
    { const char * tb_v2744 = "// --- таблица сегментов x86-64: код 64 бита, данные, задача процессора (TSS, 16 байт) ---\n"; *(const char * *)tb_grow(v_lines) = tb_v2744; }
    { const char * tb_v2745 = "// у каждого ядра процессора свой TSS (две записи по 8 байт): номер сегмента 0x18 + 16 × ядро\n"; *(const char * *)tb_grow(v_lines) = tb_v2745; }
    { const char * tb_v2746 = "TB_API uint64_t tb_gdt[3 + 2 * TB_NCPU] __attribute__((used)) = {0, 0x00AF9A000000FFFFULL, 0x00CF92000000FFFFULL};\n"; *(const char * *)tb_grow(v_lines) = tb_v2746; }
    { const char * tb_v2747 = "// TSS: ist[0] — отдельный стек для двойной ошибки (стек упёрся в сторожа — обработчику есть куда писать)\n"; *(const char * *)tb_grow(v_lines) = tb_v2747; }
    { const char * tb_v2748 = "typedef struct __attribute__((packed)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2748; }
    { const char * tb_v2749 = "    uint32_t r0; uint64_t rsp[3]; uint64_t r1; uint64_t ist[7]; uint64_t r2; uint16_t r3, iomap;\n"; *(const char * *)tb_grow(v_lines) = tb_v2749; }
    { const char * tb_v2750 = "} tb_tss64;\n"; *(const char * *)tb_grow(v_lines) = tb_v2750; }
    { const char * tb_v2751 = "TB_API tb_tss64 tb_tsss[TB_NCPU] __attribute__((aligned(16)));\n"; *(const char * *)tb_grow(v_lines) = tb_v2751; }
    { const char * tb_v2752 = "TB_API uint64_t tb_idt[2 * 256] __attribute__((aligned(16)));\n"; *(const char * *)tb_grow(v_lines) = tb_v2752; }
    { const char * tb_v2753 = "TB_API struct __attribute__((packed)) { uint16_t lim; uint64_t base; } tb_gdtr, tb_idtr;\n"; *(const char * *)tb_grow(v_lines) = tb_v2753; }
    { const char * tb_v2754 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v2754; }
    { const char * tb_v2755 = "// 49 входов: 0..31 ошибки процессора, 32..47 железо (таймер, клавиатура ...), 48 — «уступить ход».\n"; *(const char * *)tb_grow(v_lines) = tb_v2755; }
    { const char * tb_v2756 = "// Кадр на стеке (снизу вверх): 512 байт дробей и SSE (fxsave), 15 регистров, номер, код ошибки,\n"; *(const char * *)tb_grow(v_lines) = tb_v2756; }
    { const char * tb_v2757 = "// и то, что положил процессор: rip, cs, rflags, rsp, ss. Задачи переключаются сменой кадра —\n"; *(const char * *)tb_grow(v_lines) = tb_v2757; }
    { const char * tb_v2758 = "// у каждой задачи свои регистры и свои дроби лежат в её кадре.\n"; *(const char * *)tb_grow(v_lines) = tb_v2758; }
    { const char * tb_v2759 = "extern char tb_isr_base[];\n"; *(const char * *)tb_grow(v_lines) = tb_v2759; }
    { const char * tb_v2760 = "__asm__(\".text\\n.balign 16\\n.global tb_isr_base\\ntb_isr_base:\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v2760; }
    { const char * tb_v2761 = "        \".set tb_v, 0\\n.rept 50\\n.balign 16\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v2761; }
    { const char * tb_v2762 = "        \".if (tb_v == 8) || (tb_v == 10) || (tb_v == 11) || (tb_v == 12) || (tb_v == 13) || (tb_v == 14) || (tb_v == 17) || (tb_v == 21)\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v2762; }
    { const char * tb_v2763 = "        \".else\\npushq $0\\n.endif\\npushq $tb_v\\njmp tb_isr_common\\n.set tb_v, tb_v + 1\\n.endr\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v2763; }
    { const char * tb_v2764 = "        \"tb_isr_common:\\ncld\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v2764; }
    { const char * tb_v2765 = "        \"pushq %rax\\npushq %rcx\\npushq %rdx\\npushq %rbx\\npushq %rbp\\npushq %rsi\\npushq %rdi\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v2765; }
    { const char * tb_v2766 = "        \"pushq %r8\\npushq %r9\\npushq %r10\\npushq %r11\\npushq %r12\\npushq %r13\\npushq %r14\\npushq %r15\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v2766; }
    { const char * tb_v2767 = "        \"subq $512, %rsp\\nfxsave (%rsp)\\nmovq %rsp, %rdi\\ncall tb_isr\\nmovq %rax, %rsp\\ncall tb_switch_done\\nfxrstor (%rsp)\\naddq $512, %rsp\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v2767; }
    { const char * tb_v2768 = "        \"popq %r15\\npopq %r14\\npopq %r13\\npopq %r12\\npopq %r11\\npopq %r10\\npopq %r9\\npopq %r8\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v2768; }
    { const char * tb_v2769 = "        \"popq %rdi\\npopq %rsi\\npopq %rbp\\npopq %rbx\\npopq %rdx\\npopq %rcx\\npopq %rax\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v2769; }
    { const char * tb_v2770 = "        \"addq $16, %rsp\\niretq\\n\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2770; }
    { const char * tb_v2771 = "#define TB_F_VEC 79\n"; *(const char * *)tb_grow(v_lines) = tb_v2771; }
    { const char * tb_v2772 = "#define TB_F_ERR 80\n"; *(const char * *)tb_grow(v_lines) = tb_v2772; }
    { const char * tb_v2773 = "#define TB_F_RIP 81\n"; *(const char * *)tb_grow(v_lines) = tb_v2773; }
    { const char * tb_v2774 = "#define TB_FRAME (512 + 22 * 8)\n"; *(const char * *)tb_grow(v_lines) = tb_v2774; }
    { const char * tb_v2775 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v2775; }
    { const char * tb_v2776 = "// --- задачи: у каждой свой стек и свои «переменные потока» (temp, кэш длины) ---\n"; *(const char * *)tb_grow(v_lines) = tb_v2776; }
    { const char * tb_v2777 = "#define TB_TLS_MAX 512\n"; *(const char * *)tb_grow(v_lines) = tb_v2777; }
    { const char * tb_v2778 = "#define TB_NTASK 32\n"; *(const char * *)tb_grow(v_lines) = tb_v2778; }
    { const char * tb_v2779 = "#define TB_TSTACK 65536\n"; *(const char * *)tb_grow(v_lines) = tb_v2779; }
    { const char * tb_v2780 = "typedef struct { pthread_t th; volatile int done; void *res; } tb_task;\n"; *(const char * *)tb_grow(v_lines) = tb_v2780; }
    { const char * tb_v2781 = "typedef struct {\n"; *(const char * *)tb_grow(v_lines) = tb_v2781; }
    { const char * tb_v2782 = "    uint64_t *frame; int used; volatile int done;\n"; *(const char * *)tb_grow(v_lines) = tb_v2782; }
    { const char * tb_v2783 = "    void *(*run)(void *); void *arg; tb_task *t;\n"; *(const char * *)tb_grow(v_lines) = tb_v2783; }
    { const char * tb_v2784 = "    int on;                               // на каком ядре процессора идёт сейчас (-1 — ни на каком)\n"; *(const char * *)tb_grow(v_lines) = tb_v2784; }
    { const char * tb_v2785 = "    int no;                               // номер клетки: по порядку запуска (1, 2, 3 ...)\n"; *(const char * *)tb_grow(v_lines) = tb_v2785; }
    { const char * tb_v2786 = "    uint64_t gen; long long mem;          // поколение слота (для хозяина кусков) и байты клетки\n"; *(const char * *)tb_grow(v_lines) = tb_v2786; }
    { const char * tb_v2787 = "    int *locks[8]; int nlocks;            // замки, которые клетка держит сейчас\n"; *(const char * *)tb_grow(v_lines) = tb_v2787; }
    { const char * tb_v2788 = "    int svc;                              // служба (a = service f()): ей можно в запас памяти\n"; *(const char * *)tb_grow(v_lines) = tb_v2788; }
    { const char * tb_v2789 = "    int soft;                             // сейчас new_mem / grow_mem: нет памяти — ошибка, а не падение\n"; *(const char * *)tb_grow(v_lines) = tb_v2789; }
    { const char * tb_v2790 = "    unsigned char tls[TB_TLS_MAX + 16] __attribute__((aligned(16)));   // блок переменных потока + адрес самого себя\n"; *(const char * *)tb_grow(v_lines) = tb_v2790; }
    { const char * tb_v2791 = "} tb_kslot;\n"; *(const char * *)tb_grow(v_lines) = tb_v2791; }
    { const char * tb_v2792 = "TB_API tb_kslot tb_slots[TB_NTASK];          // 0 — main\n"; *(const char * *)tb_grow(v_lines) = tb_v2792; }
    { const char * tb_v2793 = "TB_API unsigned char tb_tstacks[TB_NTASK][TB_TSTACK] __attribute__((aligned(4096)));\n"; *(const char * *)tb_grow(v_lines) = tb_v2793; }
    { const char * tb_v2794 = "TB_API int tb_nlive = 1, tb_cell_count = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2794; }
    { const char * tb_v2795 = "// своё у каждой задачи (переменные потока): номер её слота; у функций прерывания tb_in_irq = 1\n"; *(const char * *)tb_grow(v_lines) = tb_v2795; }
    { const char * tb_v2796 = "TB_API _Thread_local int tb_cur = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2796; }
    { const char * tb_v2797 = "TB_API _Thread_local int tb_in_irq = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2797; }
    { const char * tb_v2798 = "TB_API unsigned char tb_fpu_init[512] __attribute__((aligned(16)));\n"; *(const char * *)tb_grow(v_lines) = tb_v2798; }
    { const char * tb_v2799 = "TB_API volatile uint64_t tb_ms = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2799; }
    { const char * tb_v2800 = "TB_API void (*tb_irq_fn[16])(void);\n"; *(const char * *)tb_grow(v_lines) = tb_v2800; }
    { const char * tb_v2801 = "TB_API uint16_t tb_pic_mask = 0xFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v2801; }
    { const char * tb_v2802 = "TB_API uint64_t tb_tls_size(void) { return (uint64_t)(tb_tls_end - tb_tls_start); }\n"; *(const char * *)tb_grow(v_lines) = tb_v2802; }
    { const char * tb_v2803 = "// блок переменных потока: начальные значения (образ от компоновщика), в конце — адрес конца\n"; *(const char * *)tb_grow(v_lines) = tb_v2803; }
    { const char * tb_v2804 = "// (так устроено у x86-64: FS указывает на конец блока, а там лежит он сам)\n"; *(const char * *)tb_grow(v_lines) = tb_v2804; }
    { const char * tb_v2805 = "TB_API unsigned char *tb_tls_fresh(unsigned char *b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2805; }
    { const char * tb_v2806 = "    uint64_t n = tb_tls_size();\n"; *(const char * *)tb_grow(v_lines) = tb_v2806; }
    { const char * tb_v2807 = "    memcpy(b, tb_tls_start, n);\n"; *(const char * *)tb_grow(v_lines) = tb_v2807; }
    { const char * tb_v2808 = "    unsigned char *tp = b + n;\n"; *(const char * *)tb_grow(v_lines) = tb_v2808; }
    { const char * tb_v2809 = "    *(uint64_t *)tp = (uint64_t)(uintptr_t)tp;\n"; *(const char * *)tb_grow(v_lines) = tb_v2809; }
    { const char * tb_v2810 = "    return tp;\n"; *(const char * *)tb_grow(v_lines) = tb_v2810; }
    { const char * tb_v2811 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2811; }
    { const char * tb_v2812 = "TB_API void tb_set_fs(unsigned char *tp) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2812; }
    { const char * tb_v2813 = "    uint64_t v = (uint64_t)(uintptr_t)tp;\n"; *(const char * *)tb_grow(v_lines) = tb_v2813; }
    { const char * tb_v2814 = "    __asm__ volatile(\"wrmsr\" : : \"c\"(0xC0000100u), \"a\"((uint32_t)v), \"d\"((uint32_t)(v >> 32)) : \"memory\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2814; }
    { const char * tb_v2815 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2815; }
    { const char * tb_v2816 = "TB_API unsigned char *tb_tls_tp(unsigned char *b) { return b + tb_tls_size(); }\n"; *(const char * *)tb_grow(v_lines) = tb_v2816; }
    { const char * tb_v2817 = "TB_INL void *tb_tls_self(void) { void *p; __asm__ volatile(\"movq %%fs:0, %0\" : \"=r\"(p)); return p; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2817; }
    { const char * tb_v2818 = "// хозяин куска: номер слота и поколение; кусок клетки, которой уже нет, никому не засчитывается\n"; *(const char * *)tb_grow(v_lines) = tb_v2818; }
    { const char * tb_v2819 = "TB_API uint64_t tb_cell_charge(size_t bytes) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2819; }
    { const char * tb_v2820 = "    if (tb_in_irq) return 0xFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v2820; }
    { const char * tb_v2821 = "    tb_kslot *s = &tb_slots[tb_cur];\n"; *(const char * *)tb_grow(v_lines) = tb_v2821; }
    { const char * tb_v2822 = "    if (tb_cur != 0 && s->mem + (long long)bytes > TB_CELL_QUOTA) return (uint64_t)-1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2822; }
    { const char * tb_v2823 = "    s->mem += (long long)bytes;\n"; *(const char * *)tb_grow(v_lines) = tb_v2823; }
    { const char * tb_v2824 = "    return (uint64_t)tb_cur | (s->gen << 8);\n"; *(const char * *)tb_grow(v_lines) = tb_v2824; }
    { const char * tb_v2825 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2825; }
    { const char * tb_v2826 = "// new_mem / grow_mem просят память «мягко»: не хватило — ответ else err, клетка живёт\n"; *(const char * *)tb_grow(v_lines) = tb_v2826; }
    { const char * tb_v2827 = "TB_API int tb_mem_soft_now(void) { return !tb_in_irq && tb_slots[tb_cur].soft > 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2827; }
    { const char * tb_v2828 = "TB_API void tb_mem_soft(int d) { if (!tb_in_irq) tb_slots[tb_cur].soft += d; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2828; }
    { const char * tb_v2829 = "TB_API size_t tb_heap_limit(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2829; }
    { const char * tb_v2830 = "    if (tb_in_irq || tb_cur == 0 || tb_slots[tb_cur].svc) return TB_HEAP;\n"; *(const char * *)tb_grow(v_lines) = tb_v2830; }
    { const char * tb_v2831 = "    return TB_HEAP - TB_RESERVE;\n"; *(const char * *)tb_grow(v_lines) = tb_v2831; }
    { const char * tb_v2832 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2832; }
    { const char * tb_v2833 = "// хватит ли клетке квоты, если её кусок вырастет на месте (иначе растём через malloc — он и уронит)\n"; *(const char * *)tb_grow(v_lines) = tb_v2833; }
    { const char * tb_v2834 = "TB_API int tb_cell_fits(uint64_t tag, long long more) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2834; }
    { const char * tb_v2835 = "    uint64_t i = tag & 0xFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v2835; }
    { const char * tb_v2836 = "    if (i == 0 || i >= TB_NTASK || tb_slots[i].gen != (tag >> 8)) return 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2836; }
    { const char * tb_v2837 = "    return tb_slots[i].mem + more <= TB_CELL_QUOTA;\n"; *(const char * *)tb_grow(v_lines) = tb_v2837; }
    { const char * tb_v2838 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2838; }
    { const char * tb_v2839 = "TB_API void tb_cell_refund(uint64_t tag, long long bytes) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2839; }
    { const char * tb_v2840 = "    uint64_t i = tag & 0xFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v2840; }
    { const char * tb_v2841 = "    if (i >= TB_NTASK || tb_slots[i].gen != (tag >> 8) || !tb_slots[i].used) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v2841; }
    { const char * tb_v2842 = "    tb_slots[i].mem -= bytes;\n"; *(const char * *)tb_grow(v_lines) = tb_v2842; }
    { const char * tb_v2843 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2843; }
    { const char * tb_v2844 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v2844; }
    { const char * tb_v2845 = "TB_API void tb_pic_apply(void) { tb_outb(0x21, (unsigned char)tb_pic_mask); tb_outb(0xA1, (unsigned char)(tb_pic_mask >> 8)); }\n"; *(const char * *)tb_grow(v_lines) = tb_v2845; }
    { const char * tb_v2846 = "TB_API void tb_irq_set(int v, void (*fn)(void)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2846; }
    { const char * tb_v2847 = "    tb_irq_fn[v - 32] = fn;\n"; *(const char * *)tb_grow(v_lines) = tb_v2847; }
    { const char * tb_v2848 = "    tb_pic_mask &= (uint16_t)~(1u << (v - 32));\n"; *(const char * *)tb_grow(v_lines) = tb_v2848; }
