    { const char * tb_v3063 = "        if (a >= (uint64_t)(uintptr_t)tb_tstacks[i] && a < (uint64_t)(uintptr_t)tb_tstacks[i] + 4096) return 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3063; }
