    { const char * tb_v3078 = "    for (int i = 1; i < TB_NTASK; i++) tb_unmap((uint64_t)(uintptr_t)tb_tstacks[i]);\n"; *(const char * *)tb_grow(v_lines) = tb_v3078; }
    { const char * tb_v3079 = "    tb_pml4[0] = (uint64_t)(uintptr_t)tb_pdpt | 3;\n"; *(const char * *)tb_grow(v_lines) = tb_v3079; }
