    { const char * tb_v3122 = "    \"выход за границы\", \"неизвестная команда\", \"нет FPU\", \"двойная ошибка\", \"\", \"плохой TSS\", \"нет сегмента\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3122; }
    { const char * tb_v3123 = "    \"ошибка стека\", \"нарушение защиты\", \"ошибка страницы\", \"\", \"ошибка дробей\", \"выравнивание\", \"проверка железа\", \"ошибка SIMD\"};\n"; *(const char * *)tb_grow(v_lines) = tb_v3123; }
    { const char * tb_v3124 = "// клетка (задача background) упала: только она и заканчивается, ядро и другие клетки живут.\n"; *(const char * *)tb_grow(v_lines) = tb_v3124; }
    { const char * tb_v3125 = "// Тот, кто её запустил, узнаёт это из .crashed (done == 2). Main и прерывание так не умеют:\n"; *(const char * *)tb_grow(v_lines) = tb_v3125; }
    { const char * tb_v3126 = "// их падение останавливает ядро\n"; *(const char * *)tb_grow(v_lines) = tb_v3126; }
    { const char * tb_v3127 = "TB_API int tb_cell_can_fall(void) { return !tb_in_irq && tb_cur != 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3127; }
    { const char * tb_v3128 = "// кто пишет строку: номер задачи + 1 (прерывание — -1, оно не ждёт)\n"; *(const char * *)tb_grow(v_lines) = tb_v3128; }
    { const char * tb_v3129 = "TB_API long long tb_out_me(void) { return tb_in_irq ? -1 : (long long)tb_cur + 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3129; }
    { const char * tb_v3130 = "// --- владение памятью (обменная куча, как в старой Омниум): у куска один хозяин — клетка.\n"; *(const char * *)tb_grow(v_lines) = tb_v3130; }
    { const char * tb_v3131 = "// Что уходит из клетки (аргументы background, текст в канале, список через move), становится\n"; *(const char * *)tb_grow(v_lines) = tb_v3131; }
    { const char * tb_v3132 = "// ничьим (метка 0, «ядро») или переходит получателю. Упала клетка — ядро возвращает всё, что\n"; *(const char * *)tb_grow(v_lines) = tb_v3132; }
    { const char * tb_v3133 = "// у неё осталось: этого больше никто не видит.\n"; *(const char * *)tb_grow(v_lines) = tb_v3133; }
    { const char * tb_v3134 = "TB_API int tb_is_piece(const void *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3134; }
    { const char * tb_v3135 = "    const unsigned char *u = p;\n"; *(const char * *)tb_grow(v_lines) = tb_v3135; }
    { const char * tb_v3136 = "    if (!p || ((uintptr_t)p & 15) || u < tb_heap + 16 || u >= tb_heap + tb_heap_top) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3136; }
    { const char * tb_v3137 = "    size_t w = *(const size_t *)(u - 16);\n"; *(const char * *)tb_grow(v_lines) = tb_v3137; }
    { const char * tb_v3138 = "    return (w & ~(size_t)0xFF) == TB_HMAGIC && (w & 0xFF) >= 4 && (w & 0xFF) < 32 && ((const uint64_t *)p)[-1] != TB_TAG_FREE;\n"; *(const char * *)tb_grow(v_lines) = tb_v3138; }
    { const char * tb_v3139 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3139; }
    { const char * tb_v3140 = "// кусок становится ничьим (его хозяин больше не платит за него и не утащит при падении)\n"; *(const char * *)tb_grow(v_lines) = tb_v3140; }
    { const char * tb_v3141 = "TB_API void tb_export(const void *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3141; }
    { const char * tb_v3142 = "    uint64_t f = tb_irq_save();\n"; *(const char * *)tb_grow(v_lines) = tb_v3142; }
    { const char * tb_v3143 = "    if (tb_is_piece(p)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3143; }
    { const char * tb_v3144 = "        uint64_t *tag = &((uint64_t *)p)[-1];\n"; *(const char * *)tb_grow(v_lines) = tb_v3144; }
    { const char * tb_v3145 = "        tb_cell_refund(*tag, (long long)tb_piece((void *)p));\n"; *(const char * *)tb_grow(v_lines) = tb_v3145; }
    { const char * tb_v3146 = "        *tag = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3146; }
