    { const char * tb_v3148 = "    tb_irq_restore(f);\n"; *(const char * *)tb_grow(v_lines) = tb_v3148; }
    { const char * tb_v3149 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3149; }
    { const char * tb_v3150 = "// кусок переходит текущей клетке (взяла из канала)\n"; *(const char * *)tb_grow(v_lines) = tb_v3150; }
    { const char * tb_v3151 = "TB_API void tb_adopt(const void *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3151; }
    { const char * tb_v3152 = "    uint64_t f = tb_irq_save();\n"; *(const char * *)tb_grow(v_lines) = tb_v3152; }
    { const char * tb_v3153 = "    if (tb_is_piece(p)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3153; }
    { const char * tb_v3154 = "        uint64_t *tag = &((uint64_t *)p)[-1];\n"; *(const char * *)tb_grow(v_lines) = tb_v3154; }
    { const char * tb_v3155 = "        tb_cell_refund(*tag, (long long)tb_piece((void *)p));\n"; *(const char * *)tb_grow(v_lines) = tb_v3155; }
    { const char * tb_v3156 = "        uint64_t t = tb_cell_charge(tb_piece((void *)p));\n"; *(const char * *)tb_grow(v_lines) = tb_v3156; }
    { const char * tb_v3157 = "        *tag = t == (uint64_t)-1 ? 0 : t;   // сверх квоты — пусть будет ничьим, клетку не роняем на приёме\n"; *(const char * *)tb_grow(v_lines) = tb_v3157; }
