    { const char * tb_v3160 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3160; }
    { const char * tb_v3161 = "// упала клетка: вернуть все куски с её меткой\n"; *(const char * *)tb_grow(v_lines) = tb_v3161; }
    { const char * tb_v3162 = "TB_API long long tb_cell_reclaim(uint64_t tag) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3162; }
    { const char * tb_v3163 = "    long long got = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3163; }
    { const char * tb_v3164 = "    if ((tag & 0xFF) == 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3164; }
    { const char * tb_v3165 = "    uint64_t f = tb_irq_save();\n"; *(const char * *)tb_grow(v_lines) = tb_v3165; }
    { const char * tb_v3166 = "    size_t at = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3166; }
    { const char * tb_v3167 = "    while (at < tb_heap_top) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3167; }
