    { const char * tb_v3173 = "            got += (long long)((size_t)1 << k);\n"; *(const char * *)tb_grow(v_lines) = tb_v3173; }
    { const char * tb_v3174 = "            p[-1] = TB_TAG_FREE;\n"; *(const char * *)tb_grow(v_lines) = tb_v3174; }
    { const char * tb_v3175 = "            tb_free0(p);\n"; *(const char * *)tb_grow(v_lines) = tb_v3175; }
    { const char * tb_v3176 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v3176; }
    { const char * tb_v3177 = "        at = next;\n"; *(const char * *)tb_grow(v_lines) = tb_v3177; }
    { const char * tb_v3178 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3178; }
    { const char * tb_v3179 = "    tb_irq_restore(f);\n"; *(const char * *)tb_grow(v_lines) = tb_v3179; }
    { const char * tb_v3180 = "    return got;\n"; *(const char * *)tb_grow(v_lines) = tb_v3180; }
    { const char * tb_v3181 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3181; }
