    { const char * tb_v3183 = "    tb_kslot *s = &tb_slots[tb_cur];\n"; *(const char * *)tb_grow(v_lines) = tb_v3183; }
    { const char * tb_v3184 = "    // замки, которые клетка держала, отпускаем: иначе на них застрянут другие\n"; *(const char * *)tb_grow(v_lines) = tb_v3184; }
    { const char * tb_v3185 = "    for (int i = 0; i < s->nlocks; i++) __atomic_store_n(s->locks[i], 0, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v3185; }
    { const char * tb_v3186 = "    s->nlocks = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3186; }
    { const char * tb_v3187 = "    char buf[200];\n"; *(const char * *)tb_grow(v_lines) = tb_v3187; }
    { const char * tb_v3188 = "    if (line > 0) snprintf(buf, sizeof buf, \"*** клетка %d упала: строка %d: %s\\n\", s->no, line, what);\n"; *(const char * *)tb_grow(v_lines) = tb_v3188; }
    { const char * tb_v3189 = "    else snprintf(buf, sizeof buf, \"*** клетка %d упала: %s\\n\", s->no, what);\n"; *(const char * *)tb_grow(v_lines) = tb_v3189; }
    { const char * tb_v3190 = "    fputs(buf, stderr);\n"; *(const char * *)tb_grow(v_lines) = tb_v3190; }
