    { const char * tb_v3192 = "    s->mem = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3192; }
    { const char * tb_v3193 = "    s->t->done = 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v3193; }
    { const char * tb_v3194 = "    s->done = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3194; }
    { const char * tb_v3195 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3195; }
    { const char * tb_v3196 = "__attribute__((noreturn)) TB_API void tb_cell_fall(const char *what, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3196; }
    { const char * tb_v3197 = "    __asm__ volatile(\"cli\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3197; }
    { const char * tb_v3198 = "    tb_cell_mark(what, line);\n"; *(const char * *)tb_grow(v_lines) = tb_v3198; }
