    { const char * tb_v3203 = "    uint64_t rip = f[TB_F_RIP], a;\n"; *(const char * *)tb_grow(v_lines) = tb_v3203; }
    { const char * tb_v3204 = "    const char *what;\n"; *(const char * *)tb_grow(v_lines) = tb_v3204; }
    { const char * tb_v3205 = "    __asm__ volatile(\"movq %%cr2, %0\" : \"=r\"(a));\n"; *(const char * *)tb_grow(v_lines) = tb_v3205; }
    { const char * tb_v3206 = "    if ((v == 14 || v == 8) && tb_is_guard(a)) what = \"стек переполнен: слишком глубокая рекурсия\";\n"; *(const char * *)tb_grow(v_lines) = tb_v3206; }
    { const char * tb_v3207 = "    else if (v == 14 && a < 4096) what = \"обращение по пустому адресу (адрес 0)\";\n"; *(const char * *)tb_grow(v_lines) = tb_v3207; }
    { const char * tb_v3208 = "    else if (v == 14 && (f[TB_F_ERR] & 2) && a >= (uint64_t)(uintptr_t)tb_code_start && a < (uint64_t)(uintptr_t)tb_code_end) what = \"запись в код программы\";\n"; *(const char * *)tb_grow(v_lines) = tb_v3208; }
    { const char * tb_v3209 = "    else if (v == 14) what = \"обращение к памяти, которой нет\";\n"; *(const char * *)tb_grow(v_lines) = tb_v3209; }
