    { const char * tb_v3211 = "    else what = v < 20 && tb_fault_name[v][0] ? tb_fault_name[v] : \"ошибка процессора\";\n"; *(const char * *)tb_grow(v_lines) = tb_v3211; }
    { const char * tb_v3212 = "    if (tb_cell_can_fall()) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3212; }
