    { const char * tb_v3219 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v3219; }
    { const char * tb_v3220 = "// все прерывания приходят сюда; ответ — кадр, в который вернуться (так переключаются задачи)\n"; *(const char * *)tb_grow(v_lines) = tb_v3220; }
    { const char * tb_v3221 = "__attribute__((used)) static uint64_t *tb_isr(uint64_t *f) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3221; }
    { const char * tb_v3222 = "    uint64_t v = f[TB_F_VEC];\n"; *(const char * *)tb_grow(v_lines) = tb_v3222; }
    { const char * tb_v3223 = "    if (v < 32) return tb_fault(v, f);\n"; *(const char * *)tb_grow(v_lines) = tb_v3223; }
    { const char * tb_v3224 = "    if (v == 48) return tb_schedule(f);\n"; *(const char * *)tb_grow(v_lines) = tb_v3224; }
    { const char * tb_v3225 = "    if (v == 49) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3225; }
    { const char * tb_v3226 = "        // таймер своего ядра процессора (APIC): 1000 раз в секунду\n"; *(const char * *)tb_grow(v_lines) = tb_v3226; }
    { const char * tb_v3227 = "        tb_lapic_w(0xB0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v3227; }
