    { const char * tb_v3231 = "    int irq = (int)v - 32;\n"; *(const char * *)tb_grow(v_lines) = tb_v3231; }
    { const char * tb_v3232 = "    if (irq == 0) tb_ms++;\n"; *(const char * *)tb_grow(v_lines) = tb_v3232; }
