    { const char * tb_v3248 = "    tb_idt[2 * v] = (a & 0xFFFFu) | (0x08ull << 16) | ((uint64_t)ist << 32) | (0x8Eull << 40) | (((a >> 16) & 0xFFFFu) << 48);\n"; *(const char * *)tb_grow(v_lines) = tb_v3248; }
