    { const char * tb_v3303 = "        if (memcmp((void *)(uintptr_t)a, \"RSD PTR \", 8) == 0) rsdp = (unsigned char *)(uintptr_t)a;\n"; *(const char * *)tb_grow(v_lines) = tb_v3303; }
    { const char * tb_v3304 = "    if (!rsdp) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3304; }
    { const char * tb_v3305 = "    unsigned char *rsdt = (unsigned char *)(uintptr_t)*(uint32_t *)(rsdp + 16);\n"; *(const char * *)tb_grow(v_lines) = tb_v3305; }
