    { const char * tb_v3307 = "    uint32_t len = *(uint32_t *)(rsdt + 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v3307; }
    { const char * tb_v3308 = "    int n = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3308; }
    { const char * tb_v3309 = "    for (uint32_t o = 36; o + 4 <= len; o += 4) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3309; }
