    { const char * tb_v3331 = "        \"  movw $0x10, %ax\\n  movw %ax, %ds\\n  movw %ax, %ss\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v3331; }
    { const char * tb_v3332 = "        \"  movl %cr4, %eax\\n  orl $0x620, %eax\\n  movl %eax, %cr4\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v3332; }
