    { const char * tb_v3342 = "        \"tb_tr_gdtr:\\n  .word 31\\n  .long 0x8000 + (tb_tr_gdt - tb_tramp)\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v3342; }
