    { const char * tb_v3344 = "        \"tb_tramp_end:\\n\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3344; }
    { const char * tb_v3345 = "TB_API void tb_lapic_timer_start(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3345; }
    { const char * tb_v3346 = "    tb_lapic_w(0x3E0, 3);                              // делитель 16\n"; *(const char * *)tb_grow(v_lines) = tb_v3346; }
