    { const char * tb_v3375 = "TB_API void tb_smp_start(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3375; }
    { const char * tb_v3376 = "    // такты APIC за 10 мс (по таймеру PIT, он уже идёт)\n"; *(const char * *)tb_grow(v_lines) = tb_v3376; }
