    { const char * tb_v4610 = "// ---------- падение по памяти: понятное сообщение вместо «Segmentation fault» ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v4610; }
    { const char * tb_v4611 = "// Чаще всего это стек: функция зовёт себя слишком глубоко. Обработчик работает\n"; *(const char * *)tb_grow(v_lines) = tb_v4611; }
    { const char * tb_v4612 = "// на своём маленьком стеке (sigaltstack), потому что основной уже кончился.\n"; *(const char * *)tb_grow(v_lines) = tb_v4612; }
    { const char * tb_v4613 = "#ifndef _WIN32\n"; *(const char * *)tb_grow(v_lines) = tb_v4613; }
    { const char * tb_v4614 = "#include <signal.h>\n"; *(const char * *)tb_grow(v_lines) = tb_v4614; }
