    { const char * tb_v4616 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v4616; }
    { const char * tb_v4617 = "// На Windows нет сигналов и sigaltstack: переполнение стека ловит обработчик\n"; *(const char * *)tb_grow(v_lines) = tb_v4617; }
    { const char * tb_v4618 = "// исключений (tb_guard_init ниже), а место для него в конце стека даёт\n"; *(const char * *)tb_grow(v_lines) = tb_v4618; }
    { const char * tb_v4619 = "// SetThreadStackGuarantee. Этот sigaltstack только помнит память потока,\n"; *(const char * *)tb_grow(v_lines) = tb_v4619; }
    { const char * tb_v4620 = "// чтобы tb_tramp_run мог её отдать, и просит у Windows запас стека.\n"; *(const char * *)tb_grow(v_lines) = tb_v4620; }
    { const char * tb_v4621 = "typedef struct { void *ss_sp; size_t ss_size; int ss_flags; } stack_t;\n"; *(const char * *)tb_grow(v_lines) = tb_v4621; }
    { const char * tb_v4622 = "#define SS_DISABLE 4\n"; *(const char * *)tb_grow(v_lines) = tb_v4622; }
    { const char * tb_v4623 = "TB_API _Thread_local void *tb_win_alt;\n"; *(const char * *)tb_grow(v_lines) = tb_v4623; }
    { const char * tb_v4624 = "TB_API int sigaltstack(const stack_t *ss, stack_t *old) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4624; }
    { const char * tb_v4625 = "    if (old) { old->ss_sp = tb_win_alt; old->ss_size = 0; old->ss_flags = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4625; }
    { const char * tb_v4626 = "    if (ss) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4626; }
    { const char * tb_v4627 = "        tb_win_alt = (ss->ss_flags & SS_DISABLE) ? 0 : ss->ss_sp;\n"; *(const char * *)tb_grow(v_lines) = tb_v4627; }
    { const char * tb_v4628 = "        if (!(ss->ss_flags & SS_DISABLE)) { ULONG g = 65536; SetThreadStackGuarantee(&g); }\n"; *(const char * *)tb_grow(v_lines) = tb_v4628; }
    { const char * tb_v4629 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4629; }
    { const char * tb_v4630 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4630; }
    { const char * tb_v4631 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4631; }
    { const char * tb_v4632 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v4632; }
    { const char * tb_v4633 = "// у каждого потока своё: где начинается его стек и сколько в нём места\n"; *(const char * *)tb_grow(v_lines) = tb_v4633; }
    { const char * tb_v4634 = "TB_API _Thread_local char *tb_main_sp;\n"; *(const char * *)tb_grow(v_lines) = tb_v4634; }
    { const char * tb_v4635 = "TB_API _Thread_local long long tb_stack_lim;\n"; *(const char * *)tb_grow(v_lines) = tb_v4635; }
    { const char * tb_v4636 = "#define TB_THREAD_STACK (8LL << 20)\n"; *(const char * *)tb_grow(v_lines) = tb_v4636; }
    { const char * tb_v4637 = "#ifndef _WIN32\n"; *(const char * *)tb_grow(v_lines) = tb_v4637; }
    { const char * tb_v4638 = "TB_API void tb_on_segv(int sig, siginfo_t *si, void *u) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4638; }
    { const char * tb_v4639 = "    (void)sig; (void)u;\n"; *(const char * *)tb_grow(v_lines) = tb_v4639; }
