    { const char * tb_v4665 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4665; }
    { const char * tb_v4666 = "// поток background или ядра: сначала ставим защиту стека, потом сама работа\n"; *(const char * *)tb_grow(v_lines) = tb_v4666; }
    { const char * tb_v4667 = "// сколько потоков background / ядер работает сейчас: уборка памяти ждёт, пока их нет\n"; *(const char * *)tb_grow(v_lines) = tb_v4667; }
    { const char * tb_v4668 = "TB_API int tb_gthreads = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4668; }
    { const char * tb_v4669 = "// короткое ожидание без сна (подсказка процессору)\n"; *(const char * *)tb_grow(v_lines) = tb_v4669; }
    { const char * tb_v4670 = "#if defined(__x86_64__) || defined(__i386__)\n"; *(const char * *)tb_grow(v_lines) = tb_v4670; }
    { const char * tb_v4671 = "#define __builtin_ia32_pause_or_yield() __builtin_ia32_pause()\n"; *(const char * *)tb_grow(v_lines) = tb_v4671; }
    { const char * tb_v4672 = "#elif defined(__aarch64__)\n"; *(const char * *)tb_grow(v_lines) = tb_v4672; }
