    { const char * tb_v4674 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v4674; }
    { const char * tb_v4675 = "#define __builtin_ia32_pause_or_yield() ((void)0)\n"; *(const char * *)tb_grow(v_lines) = tb_v4675; }
    { const char * tb_v4676 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v4676; }
    { const char * tb_v4677 = "typedef struct { void *(*run)(void *); void *arg; } tb_tramp;\n"; *(const char * *)tb_grow(v_lines) = tb_v4677; }
