    { const char * tb_v4689 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4689; }
    { const char * tb_v4690 = "// поток с 8 МБ стека (на Mac по умолчанию всего 512 КБ) и с понятным сообщением при переполнении\n"; *(const char * *)tb_grow(v_lines) = tb_v4690; }
    { const char * tb_v4691 = "TB_API int tb_thread_create(pthread_t *th, void *(*run)(void *), void *arg) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4691; }
    { const char * tb_v4692 = "    tb_tramp *t = malloc(sizeof(tb_tramp));\n"; *(const char * *)tb_grow(v_lines) = tb_v4692; }
