    { const char * tb_v4883 = "    if (p == 0) tb_crash(0, \"не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v4883; }
    { const char * tb_v4884 = "    return p;\n"; *(const char * *)tb_grow(v_lines) = tb_v4884; }
    { const char * tb_v4885 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4885; }
    { const char * tb_v4886 = "#define tb_gc_root(p, n) ((void)(p), (void)(n))\n"; *(const char * *)tb_grow(v_lines) = tb_v4886; }
    { const char * tb_v4887 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v4887; }
    { const char * tb_v4888 = "#include <setjmp.h>\n"; *(const char * *)tb_grow(v_lines) = tb_v4888; }
    { const char * tb_v4889 = "#define TB_GSH 16\n"; *(const char * *)tb_grow(v_lines) = tb_v4889; }
