    { const char * tb_v4892 = "#define TB_GBIG 32768\n"; *(const char * *)tb_grow(v_lines) = tb_v4892; }
    { const char * tb_v4893 = "// размеры мелких блоков: страница 64 КБ делится на блоки одного размера (шаг 8 байт у мелких — плотно, как подряд)\n"; *(const char * *)tb_grow(v_lines) = tb_v4893; }
    { const char * tb_v4894 = "TB_API const long long tb_gsz[TB_GNC] = {16, 24, 32, 40, 48, 56, 64, 72, 80, 96, 112, 128, 160, 192, 224, 256,\n"; *(const char * *)tb_grow(v_lines) = tb_v4894; }
    { const char * tb_v4895 = "    320, 384, 448, 512, 640, 768, 1024, 1280, 1536, 2048, 2560, 3072, 4096, 5120, 6144, 8192, 10240, 12288,\n"; *(const char * *)tb_grow(v_lines) = tb_v4895; }
    { const char * tb_v4896 = "    16384, 21840, 32768};\n"; *(const char * *)tb_grow(v_lines) = tb_v4896; }
