    { const char * tb_v4933 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4933; }
    { const char * tb_v4934 = "TB_API void tb_gmap_put(uintptr_t a, tb_gpage *pg) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4934; }
    { const char * tb_v4935 = "    tb_gpage ***d = &tb_gdir[a >> 32];\n"; *(const char * *)tb_grow(v_lines) = tb_v4935; }
    { const char * tb_v4936 = "    if (!*d) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4936; }
    { const char * tb_v4937 = "        *d = calloc(1 << 16, sizeof(tb_gpage *));\n"; *(const char * *)tb_grow(v_lines) = tb_v4937; }
    { const char * tb_v4938 = "        if (!*d) tb_crash(0, \"не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v4938; }
    { const char * tb_v4939 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4939; }
    { const char * tb_v4940 = "    (*d)[(a >> TB_GSH) & 0xFFFF] = pg;\n"; *(const char * *)tb_grow(v_lines) = tb_v4940; }
    { const char * tb_v4941 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4941; }
    { const char * tb_v4942 = "TB_API void tb_gmap_add(tb_gpage *pg, long long size) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4942; }
    { const char * tb_v4943 = "    for (long long o = 0; o < size; o += TB_GPG) tb_gmap_put((uintptr_t)pg->start + o, pg);\n"; *(const char * *)tb_grow(v_lines) = tb_v4943; }
    { const char * tb_v4944 = "    if ((uintptr_t)pg->start < tb_glo) tb_glo = (uintptr_t)pg->start;\n"; *(const char * *)tb_grow(v_lines) = tb_v4944; }
    { const char * tb_v4945 = "    if ((uintptr_t)pg->start + size > tb_ghi) tb_ghi = (uintptr_t)pg->start + size;\n"; *(const char * *)tb_grow(v_lines) = tb_v4945; }
    { const char * tb_v4946 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4946; }
    { const char * tb_v4947 = "TB_API void tb_gmap_remove(tb_gpage *pg, long long size) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4947; }
    { const char * tb_v4948 = "    for (long long o = 0; o < size; o += TB_GPG) tb_gmap_put((uintptr_t)pg->start + o, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v4948; }
    { const char * tb_v4949 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4949; }
    { const char * tb_v4950 = "// память у системы: mmap всегда отдаёт нули и выровнено по 64 КБ (лишнее по краям отдаём назад)\n"; *(const char * *)tb_grow(v_lines) = tb_v4950; }
    { const char * tb_v4951 = "#ifdef _WIN32\n"; *(const char * *)tb_grow(v_lines) = tb_v4951; }
    { const char * tb_v4952 = "// Windows: VirtualAlloc тоже даёт нули, и адрес у него всегда кратен 64 КБ — обрезать нечего.\n"; *(const char * *)tb_grow(v_lines) = tb_v4952; }
    { const char * tb_v4953 = "// munmap здесь зовётся только для целого куска из tb_gsys — это VirtualFree(MEM_RELEASE).\n"; *(const char * *)tb_grow(v_lines) = tb_v4953; }
    { const char * tb_v4954 = "TB_API char *tb_gsys(long long size) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4954; }
    { const char * tb_v4955 = "    char *m = VirtualAlloc(0, (SIZE_T)size, MEM_RESERVE | MEM_COMMIT, PAGE_READWRITE);\n"; *(const char * *)tb_grow(v_lines) = tb_v4955; }
    { const char * tb_v4956 = "    if (!m) tb_crash(0, \"не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v4956; }
    { const char * tb_v4957 = "    return m;\n"; *(const char * *)tb_grow(v_lines) = tb_v4957; }
    { const char * tb_v4958 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4958; }
    { const char * tb_v4959 = "#define munmap(p, n) (VirtualFree((p), 0, MEM_RELEASE) ? 0 : -1)\n"; *(const char * *)tb_grow(v_lines) = tb_v4959; }
    { const char * tb_v4960 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v4960; }
    { const char * tb_v4961 = "#include <sys/mman.h>\n"; *(const char * *)tb_grow(v_lines) = tb_v4961; }
    { const char * tb_v4962 = "#ifdef __linux__\n"; *(const char * *)tb_grow(v_lines) = tb_v4962; }
    { const char * tb_v4963 = "#ifndef MREMAP_MAYMOVE\n"; *(const char * *)tb_grow(v_lines) = tb_v4963; }
    { const char * tb_v4964 = "#define MREMAP_MAYMOVE 1\n"; *(const char * *)tb_grow(v_lines) = tb_v4964; }
    { const char * tb_v4965 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v4965; }
