    { const char * tb_v4968 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v4968; }
    { const char * tb_v4969 = "extern void *mremap(void *old, size_t old_size, size_t new_size, int flags, ...);\n"; *(const char * *)tb_grow(v_lines) = tb_v4969; }
    { const char * tb_v4970 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v4970; }
    { const char * tb_v4971 = "TB_API char *tb_gsys(long long size) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4971; }
    { const char * tb_v4972 = "    size_t tot = (size_t)size + (size_t)TB_GPG;\n"; *(const char * *)tb_grow(v_lines) = tb_v4972; }
    { const char * tb_v4973 = "    char *m = mmap(0, tot, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANON, -1, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v4973; }
    { const char * tb_v4974 = "    if (m == MAP_FAILED) tb_crash(0, \"не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v4974; }
    { const char * tb_v4975 = "    uintptr_t a = ((uintptr_t)m + TB_GPG - 1) & ~(uintptr_t)(TB_GPG - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v4975; }
