    { const char * tb_v4979 = "    return (char *)a;\n"; *(const char * *)tb_grow(v_lines) = tb_v4979; }
    { const char * tb_v4980 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4980; }
    { const char * tb_v4981 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v4981; }
    { const char * tb_v4982 = "// страницы по 64 КБ берём у системы пачкой по 4 МБ; пустые страницы возвращаются в запас\n"; *(const char * *)tb_grow(v_lines) = tb_v4982; }
    { const char * tb_v4983 = "TB_API char *tb_gfresh = 0, *tb_gfresh_end = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4983; }
    { const char * tb_v4984 = "TB_API void *tb_gspare = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4984; }
    { const char * tb_v4985 = "TB_API char *tb_gpage_mem(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4985; }
    { const char * tb_v4986 = "    if (tb_gspare) { void *p = tb_gspare; tb_gspare = *(void **)p; *(void **)p = 0; return p; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4986; }
    { const char * tb_v4987 = "    if (tb_gfresh == tb_gfresh_end) { tb_gfresh = tb_gsys(64 * TB_GPG); tb_gfresh_end = tb_gfresh + 64 * TB_GPG; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4987; }
