    { const char * tb_v5305 = "    // если мусора почти не нашлось (программа копит данные), следующий обход — ещё позже\n"; *(const char * *)tb_grow(v_lines) = tb_v5305; }
    { const char * tb_v5306 = "    // если мусора почти не нашлось (программа копит данные) два раза подряд — ещё реже (×8),\n"; *(const char * *)tb_grow(v_lines) = tb_v5306; }
    { const char * tb_v5307 = "    // но лишней памяти сверх «вдвое» не больше 512 МБ\n"; *(const char * *)tb_grow(v_lines) = tb_v5307; }
    { const char * tb_v5308 = "    static int tb_gkeep = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5308; }
