    { const char * tb_v5422 = "    return TB_BIT(l, i);\n"; *(const char * *)tb_grow(v_lines) = tb_v5422; }
    { const char * tb_v5423 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5423; }
    { const char * tb_v5424 = "TB_INL void tb_bset(tb_list *l, long long i, _Bool v, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5424; }
    { const char * tb_v5425 = "    if (TB_RARE((unsigned long long)i >= (unsigned long long)l->len)) tb_crash(line, \"номер за пределами списка\");\n"; *(const char * *)tb_grow(v_lines) = tb_v5425; }
    { const char * tb_v5426 = "    unsigned long long *w = (unsigned long long *)l->data + (i >> 6), m = 1ULL << (i & 63);\n"; *(const char * *)tb_grow(v_lines) = tb_v5426; }
