    { const char * tb_v5970 = "// ---------- http_get: страница из интернета через curl (есть на Mac и почти на любом Linux) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v5970; }
    { const char * tb_v5971 = "TB_API const char *tb_http_get(const char *url) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5971; }
    { const char * tb_v5972 = "    if (strncmp(url, \"http://\", 7) != 0 && strncmp(url, \"https://\", 8) != 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5972; }
    { const char * tb_v5973 = "        tb_err = tb_cat(\"адрес должен начинаться с http:// или https://: \", url);\n"; *(const char * *)tb_grow(v_lines) = tb_v5973; }
    { const char * tb_v5974 = "        return \"\";\n"; *(const char * *)tb_grow(v_lines) = tb_v5974; }
    { const char * tb_v5975 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v5975; }
    { const char * tb_v5976 = "    // адрес — в одинарных кавычках для shell: ' внутри адреса пишется как '\\''\n"; *(const char * *)tb_grow(v_lines) = tb_v5976; }
    { const char * tb_v5977 = "    size_t n = strlen(url);\n"; *(const char * *)tb_grow(v_lines) = tb_v5977; }
    { const char * tb_v5978 = "    char *cmd = malloc(n * 4 + 80);\n"; *(const char * *)tb_grow(v_lines) = tb_v5978; }
    { const char * tb_v5979 = "    if (!cmd) { tb_err = \"не хватило памяти\"; return \"\"; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5979; }
    { const char * tb_v5980 = "#ifdef _WIN32\n"; *(const char * *)tb_grow(v_lines) = tb_v5980; }
    { const char * tb_v5981 = "    // curl.exe есть в Windows 10 и новее; адрес — в двойных кавычках для cmd.exe,\n"; *(const char * *)tb_grow(v_lines) = tb_v5981; }
    { const char * tb_v5982 = "    // (внутри кавычек & | < > ^ для cmd — простые знаки), а \" внутри адреса — как %22\n"; *(const char * *)tb_grow(v_lines) = tb_v5982; }
    { const char * tb_v5983 = "    size_t k = (size_t)sprintf(cmd, \"curl.exe -fsSL --max-time 30 \\\"\");\n"; *(const char * *)tb_grow(v_lines) = tb_v5983; }
    { const char * tb_v5984 = "    for (size_t i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5984; }
    { const char * tb_v5985 = "        unsigned char ch = (unsigned char)url[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v5985; }
    { const char * tb_v5986 = "        if (ch == '\"' || ch < 32) { sprintf(cmd + k, \"%%%02X\", ch); k += 3; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5986; }
    { const char * tb_v5987 = "        else cmd[k++] = url[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v5987; }
    { const char * tb_v5988 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v5988; }
    { const char * tb_v5989 = "    strcpy(cmd + k, \"\\\" 2>NUL\");\n"; *(const char * *)tb_grow(v_lines) = tb_v5989; }
    { const char * tb_v5990 = "    FILE *p = popen(cmd, \"rb\");\n"; *(const char * *)tb_grow(v_lines) = tb_v5990; }
    { const char * tb_v5991 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v5991; }
    { const char * tb_v5992 = "    size_t k = (size_t)sprintf(cmd, \"curl -fsSL --max-time 30 '\");\n"; *(const char * *)tb_grow(v_lines) = tb_v5992; }
    { const char * tb_v5993 = "    for (size_t i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5993; }
    { const char * tb_v5994 = "        if (url[i] == '\\'') { memcpy(cmd + k, \"'\\\\''\", 4); k += 4; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5994; }
    { const char * tb_v5995 = "        else cmd[k++] = url[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v5995; }
    { const char * tb_v5996 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v5996; }
    { const char * tb_v5997 = "    strcpy(cmd + k, \"' 2>/dev/null\");\n"; *(const char * *)tb_grow(v_lines) = tb_v5997; }
    { const char * tb_v5998 = "    FILE *p = popen(cmd, \"r\");\n"; *(const char * *)tb_grow(v_lines) = tb_v5998; }
    { const char * tb_v5999 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v5999; }
    { const char * tb_v6000 = "    free(cmd);\n"; *(const char * *)tb_grow(v_lines) = tb_v6000; }
    { const char * tb_v6001 = "    if (p == 0) { tb_err = \"не могу запустить curl\"; return \"\"; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6001; }
    { const char * tb_v6002 = "    size_t cap = 4096, len = 0, got;\n"; *(const char * *)tb_grow(v_lines) = tb_v6002; }
    { const char * tb_v6003 = "    char *buf = tb_tmem(cap);\n"; *(const char * *)tb_grow(v_lines) = tb_v6003; }
    { const char * tb_v6004 = "    while ((got = fread(buf + len, 1, cap - len - 1, p)) > 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6004; }
    { const char * tb_v6005 = "        len += got;\n"; *(const char * *)tb_grow(v_lines) = tb_v6005; }
