    { const char * tb_v6599 = "    t->done = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6599; }
    { const char * tb_v6600 = "    if (tb_thread_create(&t->th, run, arg) != 0) tb_crash(0, \"не получилось запустить background\");\n"; *(const char * *)tb_grow(v_lines) = tb_v6600; }
    { const char * tb_v6601 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6601; }
    { const char * tb_v6602 = "// a = service f(): в программе с ОС служба — тот же background (запас памяти есть только в ядре)\n"; *(const char * *)tb_grow(v_lines) = tb_v6602; }
    { const char * tb_v6603 = "TB_API void tb_service_start(tb_task *t, void *(*run)(void *), void *arg) { tb_task_start(t, run, arg); }\n"; *(const char * *)tb_grow(v_lines) = tb_v6603; }
    { const char * tb_v6604 = "// a.wait: дождаться потока (один раз) и отдать адрес ответа\n"; *(const char * *)tb_grow(v_lines) = tb_v6604; }
    { const char * tb_v6605 = "TB_API void *tb_wait(tb_task *t) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6605; }
    { const char * tb_v6606 = "    if (!t->done) { pthread_join(t->th, 0); t->done = 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6606; }
    { const char * tb_v6607 = "    return t->res;\n"; *(const char * *)tb_grow(v_lines) = tb_v6607; }
    { const char * tb_v6608 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6608; }
    { const char * tb_v6609 = "// a.crashed: в обычной программе падение задачи роняет всю программу — сюда доходят только целые\n"; *(const char * *)tb_grow(v_lines) = tb_v6609; }
    { const char * tb_v6610 = "TB_API _Bool tb_crashed(tb_task *t) { tb_wait(t); return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6610; }
    { const char * tb_v6611 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v6611; }
    { const char * tb_v6612 = "TB_API int tb_dhas(tb_dict *d, const void *k) { return tb_dfind(d, k) >= 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6612; }
    { const char * tb_v6613 = "TB_API void tb_dremove(tb_dict *d, const void *k) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6613; }
    { const char * tb_v6614 = "    long long at = tb_dfind(d, k);\n"; *(const char * *)tb_grow(v_lines) = tb_v6614; }
    { const char * tb_v6615 = "    if (at < 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6615; }
    { const char * tb_v6616 = "    if (d->mode != 0) tb_dto_hash(d);\n"; *(const char * *)tb_grow(v_lines) = tb_v6616; }
    { const char * tb_v6617 = "    long long last = d->keys->len - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6617; }
    { const char * tb_v6618 = "    // на место удалённого ставим последний: порядок меняется только у него\n"; *(const char * *)tb_grow(v_lines) = tb_v6618; }
    { const char * tb_v6619 = "    memcpy(d->keys->data + at * d->keys->size, d->keys->data + last * d->keys->size, d->keys->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v6619; }
    { const char * tb_v6620 = "    memcpy(d->vals->data + at * d->vals->size, d->vals->data + last * d->vals->size, d->vals->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v6620; }
    { const char * tb_v6621 = "    d->keys->len -= 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6621; }
    { const char * tb_v6622 = "    d->vals->len -= 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6622; }
    { const char * tb_v6623 = "    tb_dreindex(d, d->nslots);\n"; *(const char * *)tb_grow(v_lines) = tb_v6623; }
    { const char * tb_v6624 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6624; }
    { const char * tb_v6625 = "TB_API tb_dict *tb_dict_from(int text, long long vsize, long long n, const void *keys, const void *vals) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6625; }
    { const char * tb_v6626 = "    tb_dict *d = tb_dict_new(text, vsize);\n"; *(const char * *)tb_grow(v_lines) = tb_v6626; }
    { const char * tb_v6627 = "    long long ksize = d->keys->size;\n"; *(const char * *)tb_grow(v_lines) = tb_v6627; }
    { const char * tb_v6628 = "    for (long long i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6628; }
    { const char * tb_v6629 = "        memcpy(tb_dput(d, (const char *)keys + i * ksize, 0), (const char *)vals + i * vsize, vsize);\n"; *(const char * *)tb_grow(v_lines) = tb_v6629; }
    { const char * tb_v6630 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6630; }
    { const char * tb_v6631 = "    return d;\n"; *(const char * *)tb_grow(v_lines) = tb_v6631; }
    { const char * tb_v6632 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6632; }
    { const char * tb_v6633 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v6633; }
    { const char * tb_v6634 = "// ---------- on all cores: цикл на всех ядрах ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v6634; }
    { const char * tb_v6635 = "// Работа делится на куски; каждое ядро берёт следующий свободный кусок,\n"; *(const char * *)tb_grow(v_lines) = tb_v6635; }
    { const char * tb_v6636 = "// пока они не кончатся (так ядра не простаивают, если куски разные по тяжести).\n"; *(const char * *)tb_grow(v_lines) = tb_v6636; }
    { const char * tb_v6637 = "// shared: каждое ядро копит своё на «листке», потом один раз добавляет под замком.\n"; *(const char * *)tb_grow(v_lines) = tb_v6637; }
    { const char * tb_v6638 = "TB_API pthread_mutex_t tb_par_lock = PTHREAD_MUTEX_INITIALIZER;\n"; *(const char * *)tb_grow(v_lines) = tb_v6638; }
    { const char * tb_v6639 = "TB_API int tb_cores(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6639; }
    { const char * tb_v6640 = "    const char *want = getenv(\"TB_CORES\");   // TB_CORES=1 — проверить на одном ядре\n"; *(const char * *)tb_grow(v_lines) = tb_v6640; }
    { const char * tb_v6641 = "    long n = want != 0 ? atol(want) : sysconf(_SC_NPROCESSORS_ONLN);\n"; *(const char * *)tb_grow(v_lines) = tb_v6641; }
    { const char * tb_v6642 = "    return n < 1 ? 1 : (n > 256 ? 256 : (int)n);\n"; *(const char * *)tb_grow(v_lines) = tb_v6642; }
    { const char * tb_v6643 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6643; }
    { const char * tb_v6644 = "#ifdef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v6644; }
    { const char * tb_v6645 = "TB_API void tb_par_run(void *(*work)(void *), void *job, long long total) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6645; }
    { const char * tb_v6646 = "    int n = tb_cores();\n"; *(const char * *)tb_grow(v_lines) = tb_v6646; }
    { const char * tb_v6647 = "    if (n > total) n = (int)total;\n"; *(const char * *)tb_grow(v_lines) = tb_v6647; }
    { const char * tb_v6648 = "    if (n < 1) n = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6648; }
    { const char * tb_v6649 = "    pthread_t t[256];\n"; *(const char * *)tb_grow(v_lines) = tb_v6649; }
    { const char * tb_v6650 = "    for (int i = 1; i < n; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v6650; }
    { const char * tb_v6651 = "        if (pthread_create(&t[i], 0, work, job) != 0) tb_crash(0, \"не получилось запустить ядро\");\n"; *(const char * *)tb_grow(v_lines) = tb_v6651; }
    { const char * tb_v6652 = "    work(job);\n"; *(const char * *)tb_grow(v_lines) = tb_v6652; }
    { const char * tb_v6653 = "    for (int i = 1; i < n; i++) pthread_join(t[i], 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v6653; }
    { const char * tb_v6654 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6654; }
    { const char * tb_v6655 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v6655; }
    { const char * tb_v6656 = "// Готовые потоки: создаются один раз (при первом on all cores) и ждут работу.\n"; *(const char * *)tb_grow(v_lines) = tb_v6656; }
    { const char * tb_v6657 = "// Раньше каждый цикл на ядрах создавал и закрывал потоки — для коротких циклов это было дольше самой работы.\n"; *(const char * *)tb_grow(v_lines) = tb_v6657; }
    { const char * tb_v6658 = "TB_API pthread_mutex_t tb_pool_m = PTHREAD_MUTEX_INITIALIZER;\n"; *(const char * *)tb_grow(v_lines) = tb_v6658; }
    { const char * tb_v6659 = "TB_API pthread_cond_t tb_pool_go = PTHREAD_COND_INITIALIZER, tb_pool_end = PTHREAD_COND_INITIALIZER;\n"; *(const char * *)tb_grow(v_lines) = tb_v6659; }
    { const char * tb_v6660 = "TB_API int tb_pool_n = 0, tb_pool_want = 0, tb_pool_busy = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6660; }
    { const char * tb_v6661 = "TB_API volatile long long tb_pool_gen = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6661; }
    { const char * tb_v6662 = "TB_API volatile int tb_pool_left = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6662; }
    { const char * tb_v6663 = "TB_API void *(*tb_pool_work)(void *) = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6663; }
    { const char * tb_v6664 = "TB_API void *tb_pool_job = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6664; }
    { const char * tb_v6665 = "TB_API void *tb_pool_loop(void *arg) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6665; }
    { const char * tb_v6666 = "    int me = (int)(long long)arg;\n"; *(const char * *)tb_grow(v_lines) = tb_v6666; }
    { const char * tb_v6667 = "    // поток пула не считается «работающим», пока ждёт: уборка памяти может идти\n"; *(const char * *)tb_grow(v_lines) = tb_v6667; }
    { const char * tb_v6668 = "    __atomic_sub_fetch(&tb_gthreads, 1, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v6668; }
    { const char * tb_v6669 = "    long long seen = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6669; }
    { const char * tb_v6670 = "    for (;;) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6670; }
    { const char * tb_v6671 = "        // немного ждём без сна: циклы на ядрах часто идут один за другим\n"; *(const char * *)tb_grow(v_lines) = tb_v6671; }
    { const char * tb_v6672 = "        for (int spin = 0; spin < 20000 && __atomic_load_n(&tb_pool_gen, __ATOMIC_ACQUIRE) == seen; spin++)\n"; *(const char * *)tb_grow(v_lines) = tb_v6672; }
    { const char * tb_v6673 = "            __builtin_ia32_pause_or_yield();\n"; *(const char * *)tb_grow(v_lines) = tb_v6673; }
    { const char * tb_v6674 = "        pthread_mutex_lock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v6674; }
    { const char * tb_v6675 = "        while (tb_pool_gen == seen) pthread_cond_wait(&tb_pool_go, &tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v6675; }
    { const char * tb_v6676 = "        seen = tb_pool_gen;\n"; *(const char * *)tb_grow(v_lines) = tb_v6676; }
    { const char * tb_v6677 = "        int mine = me < tb_pool_want;\n"; *(const char * *)tb_grow(v_lines) = tb_v6677; }
    { const char * tb_v6678 = "        void *(*work)(void *) = tb_pool_work;\n"; *(const char * *)tb_grow(v_lines) = tb_v6678; }
    { const char * tb_v6679 = "        void *job = tb_pool_job;\n"; *(const char * *)tb_grow(v_lines) = tb_v6679; }
    { const char * tb_v6680 = "        pthread_mutex_unlock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v6680; }
    { const char * tb_v6681 = "        if (!mine) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v6681; }
    { const char * tb_v6682 = "        work(job);\n"; *(const char * *)tb_grow(v_lines) = tb_v6682; }
    { const char * tb_v6683 = "        __atomic_sub_fetch(&tb_gthreads, 1, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v6683; }
    { const char * tb_v6684 = "        if (__atomic_sub_fetch(&tb_pool_left, 1, __ATOMIC_ACQ_REL) == 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6684; }
    { const char * tb_v6685 = "            pthread_mutex_lock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v6685; }
    { const char * tb_v6686 = "            pthread_cond_signal(&tb_pool_end);\n"; *(const char * *)tb_grow(v_lines) = tb_v6686; }
    { const char * tb_v6687 = "            pthread_mutex_unlock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v6687; }
    { const char * tb_v6688 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v6688; }
    { const char * tb_v6689 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6689; }
    { const char * tb_v6690 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6690; }
    { const char * tb_v6691 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6691; }
    { const char * tb_v6692 = "TB_API void tb_par_run(void *(*work)(void *), void *job, long long total) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6692; }
    { const char * tb_v6693 = "    int n = tb_cores();\n"; *(const char * *)tb_grow(v_lines) = tb_v6693; }
    { const char * tb_v6694 = "    if (n > total) n = (int)total;\n"; *(const char * *)tb_grow(v_lines) = tb_v6694; }
    { const char * tb_v6695 = "    if (n < 1) n = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6695; }
    { const char * tb_v6696 = "    if (n == 1) { work(job); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6696; }
    { const char * tb_v6697 = "    // пул уже занят (цикл на ядрах из background или изнутри другого) — по-старому, своими потоками\n"; *(const char * *)tb_grow(v_lines) = tb_v6697; }
    { const char * tb_v6698 = "    if (__atomic_exchange_n(&tb_pool_busy, 1, __ATOMIC_ACQ_REL)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6698; }
    { const char * tb_v6699 = "        pthread_t t[256];\n"; *(const char * *)tb_grow(v_lines) = tb_v6699; }
    { const char * tb_v6700 = "        for (int i = 1; i < n; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v6700; }
    { const char * tb_v6701 = "            if (tb_thread_create(&t[i], work, job) != 0) tb_crash(0, \"не получилось запустить ядро\");\n"; *(const char * *)tb_grow(v_lines) = tb_v6701; }
    { const char * tb_v6702 = "        work(job);\n"; *(const char * *)tb_grow(v_lines) = tb_v6702; }
    { const char * tb_v6703 = "        for (int i = 1; i < n; i++) pthread_join(t[i], 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v6703; }
    { const char * tb_v6704 = "        return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6704; }
    { const char * tb_v6705 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6705; }
    { const char * tb_v6706 = "    while (tb_pool_n < n - 1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6706; }
    { const char * tb_v6707 = "        pthread_t th;\n"; *(const char * *)tb_grow(v_lines) = tb_v6707; }
    { const char * tb_v6708 = "        if (tb_thread_create(&th, tb_pool_loop, (void *)(long long)tb_pool_n) != 0) tb_crash(0, \"не получилось запустить ядро\");\n"; *(const char * *)tb_grow(v_lines) = tb_v6708; }
    { const char * tb_v6709 = "        pthread_detach(th);\n"; *(const char * *)tb_grow(v_lines) = tb_v6709; }
    { const char * tb_v6710 = "        tb_pool_n++;\n"; *(const char * *)tb_grow(v_lines) = tb_v6710; }
    { const char * tb_v6711 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6711; }
    { const char * tb_v6712 = "    pthread_mutex_lock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v6712; }
    { const char * tb_v6713 = "    tb_pool_work = work; tb_pool_job = job; tb_pool_want = n - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6713; }
    { const char * tb_v6714 = "    __atomic_store_n(&tb_pool_left, n - 1, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v6714; }
    { const char * tb_v6715 = "    __atomic_add_fetch(&tb_gthreads, n - 1, __ATOMIC_ACQ_REL);\n"; *(const char * *)tb_grow(v_lines) = tb_v6715; }
    { const char * tb_v6716 = "    __atomic_add_fetch(&tb_pool_gen, 1, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v6716; }
    { const char * tb_v6717 = "    pthread_cond_broadcast(&tb_pool_go);\n"; *(const char * *)tb_grow(v_lines) = tb_v6717; }
    { const char * tb_v6718 = "    pthread_mutex_unlock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v6718; }
    { const char * tb_v6719 = "    work(job);\n"; *(const char * *)tb_grow(v_lines) = tb_v6719; }
    { const char * tb_v6720 = "    if (__atomic_load_n(&tb_pool_left, __ATOMIC_ACQUIRE) != 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6720; }
    { const char * tb_v6721 = "        for (int spin = 0; spin < 20000 && __atomic_load_n(&tb_pool_left, __ATOMIC_ACQUIRE) != 0; spin++)\n"; *(const char * *)tb_grow(v_lines) = tb_v6721; }
    { const char * tb_v6722 = "            __builtin_ia32_pause_or_yield();\n"; *(const char * *)tb_grow(v_lines) = tb_v6722; }
    { const char * tb_v6723 = "        pthread_mutex_lock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v6723; }
    { const char * tb_v6724 = "        while (__atomic_load_n(&tb_pool_left, __ATOMIC_ACQUIRE) != 0) pthread_cond_wait(&tb_pool_end, &tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v6724; }
    { const char * tb_v6725 = "        pthread_mutex_unlock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v6725; }
    { const char * tb_v6726 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6726; }
    { const char * tb_v6727 = "    __atomic_store_n(&tb_pool_busy, 0, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v6727; }
    { const char * tb_v6728 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6728; }
    { const char * tb_v6729 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v6729; }
    { const char * tb_v6730 = "TB_API long long tb_par_step(long long total) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6730; }
    { const char * tb_v6731 = "    long long s = total / ((long long)tb_cores() * 16);\n"; *(const char * *)tb_grow(v_lines) = tb_v6731; }
    { const char * tb_v6732 = "    return s < 1 ? 1 : s;\n"; *(const char * *)tb_grow(v_lines) = tb_v6732; }
    { const char * tb_v6733 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6733; }
    { const char * tb_v6734 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v6734; }
    { const char * tb_v6735 = "// ---------- биты, адреса, порты, замки (danger и lock) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v6735; }
    { const char * tb_v6736 = "TB_INL long long tb_band(long long a, long long b) { return a & b; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6736; }
    { const char * tb_v6737 = "TB_INL long long tb_bor(long long a, long long b) { return a | b; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6737; }
    { const char * tb_v6738 = "TB_INL long long tb_bxor(long long a, long long b) { return a ^ b; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6738; }
