    { const char * tb_v6800 = "        if (tb_mem_all[i].live) { if (!n) first = tb_mem_all[i].line; n++; bytes += (long long)tb_mem_all[i].n; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6800; }
    { const char * tb_v6801 = "    if (n && tb_mem_check) fprintf(stderr, tb_tr(\"TB_MEM_CHECK: не освобождено блоков %lld (%lld байт), первый из new_mem в строке %d\\n\"), n, bytes, first);\n"; *(const char * *)tb_grow(v_lines) = tb_v6801; }
    { const char * tb_v6802 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6802; }
    { const char * tb_v6803 = "// TB_MEM_CHECK: можно ли трогать байты [a, a + n)\n"; *(const char * *)tb_grow(v_lines) = tb_v6803; }
    { const char * tb_v6804 = "static void tb_mem_touch(uintptr_t a, uint64_t n, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6804; }
    { const char * tb_v6805 = "    if (n == 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6805; }
    { const char * tb_v6806 = "    tb_mem_lock();\n"; *(const char * *)tb_grow(v_lines) = tb_v6806; }
