    { const char * tb_v6812 = "            char buf[400];\n"; *(const char * *)tb_grow(v_lines) = tb_v6812; }
    { const char * tb_v6813 = "            snprintf(buf, sizeof buf, \"эта память уже освобождена: free_mem в строке %d\", b->fline);\n"; *(const char * *)tb_grow(v_lines) = tb_v6813; }
