    { const char * tb_v6815 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v6815; }
    { const char * tb_v6816 = "        if (a < b->a || a + n > b->a + b->n) tb_mem_die(line, \"чтение или запись за краем блока\", b->line);\n"; *(const char * *)tb_grow(v_lines) = tb_v6816; }
    { const char * tb_v6817 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6817; }
