    { const char * tb_v7496 = "            while (more-- > 0 && (*p & 0xC0) == 0x80) u = (u << 6) | (*p++ & 0x3F);\n"; *(const char * *)tb_grow(v_lines) = tb_v7496; }
    { const char * tb_v7497 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v7497; }
    { const char * tb_v7498 = "        tb_type_cp(u);\n"; *(const char * *)tb_grow(v_lines) = tb_v7498; }
