    { const char * tb_v8931 = "    uint32_t compositeAlpha, presentMode; VkBool32 clipped; VkSwapchainKHR oldSwapchain; } VkSwapchainCreateInfoKHR;\n"; *(const char * *)tb_grow(v_lines) = tb_v8931; }
