    { const char * tb_v12094 = "    if (tb_my >= tb_gh) tb_my = tb_gh - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v12094; }
    { const char * tb_v12095 = "    int down = tb_mpk[0] & 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v12095; }
    { const char * tb_v12096 = "    if (down && !tb_mdown) tb_mtap = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v12096; }
