    { const char * tb_v12104 = "TB_API void tb_mouse_init(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v12104; }
    { const char * tb_v12105 = "    uint64_t f = tb_irq_save();\n"; *(const char * *)tb_grow(v_lines) = tb_v12105; }
    { const char * tb_v12106 = "    tb_ps2_wait_in(); tb_outb(0x64, 0xA8);        // включить вход мыши\n"; *(const char * *)tb_grow(v_lines) = tb_v12106; }
