    { const char * tb_v13716 = "        if (tb_wn > 1) { int w = tb_wfind((uintptr_t)e.xany.window); if (w >= 0) tb_wswitch(w); }   // событие другого окна\n"; *(const char * *)tb_grow(v_lines) = tb_v13716; }
