    { const char * tb_v13744 = "// TB_GPU_CHECK: проба смешивания. Видеокарты считают смешивание по-своему (AMD на Mac — с малой\n"; *(const char * *)tb_grow(v_lines) = tb_v13744; }
    { const char * tb_v13745 = "// точностью, ошибка зависит и от цвета буквы, и от фона), поэтому проба берёт все сочетания:\n"; *(const char * *)tb_grow(v_lines) = tb_v13745; }
    { const char * tb_v13746 = "// цвет c, фон d, прозрачность a — 256 × 256 × 256 точек, кадр за кадром, и процессор дальше\n"; *(const char * *)tb_grow(v_lines) = tb_v13746; }
    { const char * tb_v13747 = "// смешивает по этой таблице (tb_blend_lut[c][d][a]). Делается один раз, когда есть и окно, и шрифт.\n"; *(const char * *)tb_grow(v_lines) = tb_v13747; }
    { const char * tb_v13748 = "// После пробы кадр видеокарты снова становится таким же, как у процессора (копия tb_px)\n"; *(const char * *)tb_grow(v_lines) = tb_v13748; }
    { const char * tb_v13749 = "TB_API void tb_gpu_blend_probe(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13749; }
    { const char * tb_v13750 = "    if (!tb_gpu_on || !tb_gpu_check || tb_blend_cal || !tb_px || !tb_nfonts) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v13750; }
    { const char * tb_v13751 = "    uint8_t *lut = malloc((size_t)1 << 24);\n"; *(const char * *)tb_grow(v_lines) = tb_v13751; }
    { const char * tb_v13752 = "    if (!lut) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v13752; }
    { const char * tb_v13753 = "    size_t n = (size_t)tb_gw * tb_gh, p0 = tb_imgpx_n, need = p0 + 3 * n;\n"; *(const char * *)tb_grow(v_lines) = tb_v13753; }
    { const char * tb_v13754 = "    int n0 = tb_nimg;\n"; *(const char * *)tb_grow(v_lines) = tb_v13754; }
    { const char * tb_v13755 = "    uint32_t *all = need <= 0xFFFFFFFFu ? realloc(tb_imgpx, need * 4) : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v13755; }
    { const char * tb_v13756 = "    tb_image *list = realloc(tb_imgs, (size_t)(n0 + 3) * sizeof(tb_image));\n"; *(const char * *)tb_grow(v_lines) = tb_v13756; }
    { const char * tb_v13757 = "    if (all) tb_imgpx = all;\n"; *(const char * *)tb_grow(v_lines) = tb_v13757; }
    { const char * tb_v13758 = "    if (list) tb_imgs = list;\n"; *(const char * *)tb_grow(v_lines) = tb_v13758; }
    { const char * tb_v13759 = "    if (!all || !list) { free(lut); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v13759; }
    { const char * tb_v13760 = "    for (int k = 0; k < 3; k++) { tb_imgs[n0 + k].w = tb_gw; tb_imgs[n0 + k].h = tb_gh; tb_imgs[n0 + k].off = (uint32_t)(p0 + k * n); }\n"; *(const char * *)tb_grow(v_lines) = tb_v13760; }
    { const char * tb_v13761 = "    tb_nimg = n0 + 3; tb_imgpx_n = need;\n"; *(const char * *)tb_grow(v_lines) = tb_v13761; }
    { const char * tb_v13762 = "    uint32_t *keep = tb_imgpx + p0 + 2 * n;   // кадр процессора: вернуть его видеокарте после пробы\n"; *(const char * *)tb_grow(v_lines) = tb_v13762; }
    { const char * tb_v13763 = "    for (size_t q = 0; q < n; q++) keep[q] = 0xFF000000u | tb_px[q];\n"; *(const char * *)tb_grow(v_lines) = tb_v13763; }
    { const char * tb_v13764 = "    tb_gpu_probing = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v13764; }
    { const char * tb_v13765 = "    int ok = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v13765; }
    { const char * tb_v13766 = "    for (size_t from = 0; from < ((size_t)1 << 24) && ok; from += n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13766; }
    { const char * tb_v13767 = "        uint32_t *bg = tb_imgpx + p0, *fg = bg + n;\n"; *(const char * *)tb_grow(v_lines) = tb_v13767; }
    { const char * tb_v13768 = "        for (size_t q = 0; q < n; q++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13768; }
    { const char * tb_v13769 = "            size_t i = (from + q) & 0xFFFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v13769; }
    { const char * tb_v13770 = "            uint32_t c = (uint32_t)(i >> 16), d = (uint32_t)(i >> 8) & 255, a = (uint32_t)i & 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v13770; }
    { const char * tb_v13771 = "            bg[q] = 0xFF000000u | d * 0x010101u;\n"; *(const char * *)tb_grow(v_lines) = tb_v13771; }
    { const char * tb_v13772 = "            fg[q] = (a << 24) | c * 0x010101u;\n"; *(const char * *)tb_grow(v_lines) = tb_v13772; }
    { const char * tb_v13773 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v13773; }
    { const char * tb_v13774 = "        tb_img_dirty = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v13774; }
    { const char * tb_v13775 = "        tb_gpu_image(n0, 0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v13775; }
    { const char * tb_v13776 = "        tb_gpu_image_a(n0 + 1, 0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v13776; }
    { const char * tb_v13777 = "        tb_gpu_flush(1);\n"; *(const char * *)tb_grow(v_lines) = tb_v13777; }
    { const char * tb_v13778 = "        if (!tb_gpu_back) { ok = 0; break; }\n"; *(const char * *)tb_grow(v_lines) = tb_v13778; }
    { const char * tb_v13779 = "        for (size_t q = 0; q < n && from + q < ((size_t)1 << 24); q++) lut[from + q] = (uint8_t)(tb_gpu_back[q] & 255);\n"; *(const char * *)tb_grow(v_lines) = tb_v13779; }
    { const char * tb_v13780 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v13780; }
    { const char * tb_v13781 = "    tb_gpu_image(n0 + 2, 0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v13781; }
    { const char * tb_v13782 = "    tb_gpu_flush(1);\n"; *(const char * *)tb_grow(v_lines) = tb_v13782; }
    { const char * tb_v13783 = "    tb_gpu_probing = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v13783; }
    { const char * tb_v13784 = "    tb_nimg = n0; tb_imgpx_n = p0; tb_img_dirty = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v13784; }
    { const char * tb_v13785 = "    if (!ok) { free(lut); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v13785; }
    { const char * tb_v13786 = "    tb_blend_lut = lut;\n"; *(const char * *)tb_grow(v_lines) = tb_v13786; }
    { const char * tb_v13787 = "    tb_blend_cal = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v13787; }
    { const char * tb_v13788 = "    const char *e = getenv(\"TB_GPU_INFO\");\n"; *(const char * *)tb_grow(v_lines) = tb_v13788; }
    { const char * tb_v13789 = "    if (e && e[0] == '1') {\n"; *(const char * *)tb_grow(v_lines) = tb_v13789; }
    { const char * tb_v13790 = "        long long diff = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v13790; }
    { const char * tb_v13791 = "        for (size_t i = 0; i < ((size_t)1 << 24); i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13791; }
    { const char * tb_v13792 = "            uint32_t c = (uint32_t)(i >> 16), d = (uint32_t)(i >> 8) & 255, a = (uint32_t)i & 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v13792; }
    { const char * tb_v13793 = "            uint32_t w = a == 0 ? d : (c * a + 127) / 255 + (d * (255 - a) + 127) / 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v13793; }
    { const char * tb_v13794 = "            diff += lut[i] != w;\n"; *(const char * *)tb_grow(v_lines) = tb_v13794; }
    { const char * tb_v13795 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v13795; }
    { const char * tb_v13796 = "        fprintf(stderr, tb_tr(\"TB_GPU_CHECK: смешивание на этой видеокарте не как округление к ближайшему: %lld из %d\\n\"), diff, 1 << 24);\n"; *(const char * *)tb_grow(v_lines) = tb_v13796; }
    { const char * tb_v13797 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v13797; }
    { const char * tb_v13798 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v13798; }
    { const char * tb_v13799 = "// window_sharp(): окно в настоящих точках экрана (Retina, 150% и 200% на Windows). Размер в window_open\n"; *(const char * *)tb_grow(v_lines) = tb_v13799; }
    { const char * tb_v13800 = "// остаётся в «обычных» точках, а кадр, window_w/h и мышь — в настоящих; window_scale() — во сколько раз\n"; *(const char * *)tb_grow(v_lines) = tb_v13800; }
    { const char * tb_v13801 = "TB_API double tb_gfx_scale(void);   // своя у каждой системы\n"; *(const char * *)tb_grow(v_lines) = tb_v13801; }
    { const char * tb_v13802 = "TB_API void tb_window_sharp(void) { if (!tb_px) tb_sharp = 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v13802; }
    { const char * tb_v13803 = "TB_API double tb_window_scale(void) { return tb_sc; }\n"; *(const char * *)tb_grow(v_lines) = tb_v13803; }
    { const char * tb_v13804 = "// ---- несколько окон (1.3): window_new, window_use, window_close, window_shown ----\n"; *(const char * *)tb_grow(v_lines) = tb_v13804; }
    { const char * tb_v13805 = "// Главное окно (window_open) — номер 0. У каждого окна свои точки, размер, мышь, клавиши и глубина 3D.\n"; *(const char * *)tb_grow(v_lines) = tb_v13805; }
    { const char * tb_v13806 = "// Текущее окно лежит в обычных переменных (tb_px, tb_gw, tb_keys ...), остальные ждут в tb_wins.\n"; *(const char * *)tb_grow(v_lines) = tb_v13806; }
    { const char * tb_v13807 = "// Новые окна рисует процессор; видеокарта — у главного окна\n"; *(const char * *)tb_grow(v_lines) = tb_v13807; }
    { const char * tb_v13808 = "typedef struct {\n"; *(const char * *)tb_grow(v_lines) = tb_v13808; }
    { const char * tb_v13809 = "    int used;\n"; *(const char * *)tb_grow(v_lines) = tb_v13809; }
    { const char * tb_v13810 = "    uint32_t *px; int gw, gh, gclosed, mx, my, mdown, mtap, wheel; double wheel_f;\n"; *(const char * *)tb_grow(v_lines) = tb_v13810; }
    { const char * tb_v13811 = "    int mside[2], mside_tap[2], ntyped; char typed[512];\n"; *(const char * *)tb_grow(v_lines) = tb_v13811; }
    { const char * tb_v13812 = "    unsigned char keys[256], ktap[256];\n"; *(const char * *)tb_grow(v_lines) = tb_v13812; }
    { const char * tb_v13813 = "    int new_w, new_h, resizable, gpu_on, zclr, gzclr; uint32_t *zb; long long zb_n;\n"; *(const char * *)tb_grow(v_lines) = tb_v13813; }
