    { const char * tb_v13973 = "// показать кадр, принять клавиши и мышь, держать 60 кадров в секунду; false — окно закрыли\n"; *(const char * *)tb_grow(v_lines) = tb_v13973; }
    { const char * tb_v13974 = "// окно поменяло размер: новый кадр, старое остаётся в левом верхнем углу, новое место — чёрное\n"; *(const char * *)tb_grow(v_lines) = tb_v13974; }
    { const char * tb_v13975 = "TB_API void tb_apply_resize(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13975; }
    { const char * tb_v13976 = "    if (!tb_new_w) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v13976; }
