    { const char * tb_v14000 = "TB_API long long tb_fps(void) { return tb_fps_v ? tb_fps_v : tb_frame_ms_v > 0 ? (long long)(1000 / tb_frame_ms_v) : 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v14000; }
    { const char * tb_v14001 = "// показать кадр, принять клавиши и мышь, держать частоту кадров; false — окно закрыли\n"; *(const char * *)tb_grow(v_lines) = tb_v14001; }
    { const char * tb_v14002 = "TB_API int tb_window_alive(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14002; }
    { const char * tb_v14003 = "    if (tb_wn > 1) tb_windows_show();\n"; *(const char * *)tb_grow(v_lines) = tb_v14003; }
    { const char * tb_v14004 = "    if (!tb_px || tb_gclosed) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14004; }
    { const char * tb_v14005 = "    TB_SCENE();        // сцена 3D, которая ждала (тени, прозрачные) — в этот кадр\n"; *(const char * *)tb_grow(v_lines) = tb_v14005; }
    { const char * tb_v14006 = "    tb_gfx_events();   // здесь показывается прошлый кадр\n"; *(const char * *)tb_grow(v_lines) = tb_v14006; }
    { const char * tb_v14007 = "    if (tb_wn > 1) tb_windows_after();\n"; *(const char * *)tb_grow(v_lines) = tb_v14007; }
    { const char * tb_v14008 = "    tb_zclr = tb_gzclr = 1;   // новый кадр: глубина 3D начинается заново\n"; *(const char * *)tb_grow(v_lines) = tb_v14008; }
    { const char * tb_v14009 = "    tb_apply_resize();\n"; *(const char * *)tb_grow(v_lines) = tb_v14009; }
    { const char * tb_v14010 = "    // TB_FPS_FREE=1 — без ограничения (для замеров скорости), как set_fps(0)\n"; *(const char * *)tb_grow(v_lines) = tb_v14010; }
    { const char * tb_v14011 = "    static int free_fps = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14011; }
    { const char * tb_v14012 = "    if (free_fps < 0) free_fps = getenv(\"TB_FPS_FREE\") != 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14012; }
    { const char * tb_v14013 = "    long long now = tb_time_us(), period = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14013; }
    { const char * tb_v14014 = "    if (!tb_last_us) tb_last_us = now;\n"; *(const char * *)tb_grow(v_lines) = tb_v14014; }
    { const char * tb_v14015 = "    if (free_fps || tb_fps_want == 0) period = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14015; }
    { const char * tb_v14016 = "    else if (tb_fps_want > 0) period = 1000000 / tb_fps_want;\n"; *(const char * *)tb_grow(v_lines) = tb_v14016; }
    { const char * tb_v14017 = "    // как у экрана: видеокарта сама ждёт обновления экрана (60 Гц — 60 кадров, 120 Гц — 120);\n"; *(const char * *)tb_grow(v_lines) = tb_v14017; }
    { const char * tb_v14018 = "    // кадр пришёл быстрее 4 мс — экран частоту не держит, держим сами 60 кадров в секунду\n"; *(const char * *)tb_grow(v_lines) = tb_v14018; }
    { const char * tb_v14019 = "    else if (!tb_gpu_on || now - tb_last_us < 4000) period = 16667;\n"; *(const char * *)tb_grow(v_lines) = tb_v14019; }
    { const char * tb_v14020 = "    if (period && now - tb_last_us < period) { usleep((useconds_t)(period - (now - tb_last_us))); now = tb_time_us(); }\n"; *(const char * *)tb_grow(v_lines) = tb_v14020; }
    { const char * tb_v14021 = "    tb_frame_ms_v = (now - tb_last_us) / 1000.0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14021; }
    { const char * tb_v14022 = "    tb_last_us = now;\n"; *(const char * *)tb_grow(v_lines) = tb_v14022; }
    { const char * tb_v14023 = "    if (!tb_fps_t0) tb_fps_t0 = now;\n"; *(const char * *)tb_grow(v_lines) = tb_v14023; }
    { const char * tb_v14024 = "    tb_fps_n++;\n"; *(const char * *)tb_grow(v_lines) = tb_v14024; }
    { const char * tb_v14025 = "    if (now - tb_fps_t0 >= 1000000) { tb_fps_v = tb_fps_n * 1000000 / (now - tb_fps_t0); tb_fps_n = 0; tb_fps_t0 = now; }\n"; *(const char * *)tb_grow(v_lines) = tb_v14025; }
    { const char * tb_v14026 = "    tb_last_frame = now / 1000;\n"; *(const char * *)tb_grow(v_lines) = tb_v14026; }
    { const char * tb_v14027 = "    return !tb_gclosed;\n"; *(const char * *)tb_grow(v_lines) = tb_v14027; }
    { const char * tb_v14028 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14028; }
    { const char * tb_v14029 = "TB_INL void tb_put(long long x, long long y, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14029; }
    { const char * tb_v14030 = "    if (tb_px && x >= 0 && y >= 0 && x < tb_gw && y < tb_gh) tb_px[y * tb_gw + x] = (uint32_t)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v14030; }
    { const char * tb_v14031 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14031; }
    { const char * tb_v14032 = "// на видеокарте фигуры записываются (tb_gpu_*), на процессоре — рисуются сразу в tb_px.\n"; *(const char * *)tb_grow(v_lines) = tb_v14032; }
    { const char * tb_v14033 = "// TB_GPU_CHECK=1: и то и другое, кадры сверяются\n"; *(const char * *)tb_grow(v_lines) = tb_v14033; }
    { const char * tb_v14034 = "#define TB_CPU_DRAW (!tb_gpu_on || tb_gpu_check)\n"; *(const char * *)tb_grow(v_lines) = tb_v14034; }
    { const char * tb_v14035 = "TB_API long long tb_mdrawn = 0, tb_mdrawn_last = 0;   // сколько draw_mesh дошло до рисования (не отсечено) в кадре\n"; *(const char * *)tb_grow(v_lines) = tb_v14035; }
    { const char * tb_v14036 = "TB_API void tb_clear_window(long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14036; }
    { const char * tb_v14037 = "    TB_SCENE();\n"; *(const char * *)tb_grow(v_lines) = tb_v14037; }
    { const char * tb_v14038 = "    tb_mdrawn_last = tb_mdrawn; tb_mdrawn = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14038; }
    { const char * tb_v14039 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v14039; }
    { const char * tb_v14040 = "    if (tb_gpu_on) { tb_gin = 0; tb_gpu_rect(0, 0, tb_gw, tb_gh, c & 0xFFFFFF); }   // всё прежнее закрашено\n"; *(const char * *)tb_grow(v_lines) = tb_v14040; }
    { const char * tb_v14041 = "    if (TB_CPU_DRAW) for (long long i = 0; i < (long long)tb_gw * tb_gh; i++) tb_px[i] = (uint32_t)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v14041; }
    { const char * tb_v14042 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14042; }
    { const char * tb_v14043 = "TB_API void tb_draw_pixel(long long x, long long y, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14043; }
    { const char * tb_v14044 = "    TB_SCENE();\n"; *(const char * *)tb_grow(v_lines) = tb_v14044; }
    { const char * tb_v14045 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v14045; }
    { const char * tb_v14046 = "    if (tb_gpu_on) tb_gpu_rect(x, y, 1, 1, c & 0xFFFFFF);\n"; *(const char * *)tb_grow(v_lines) = tb_v14046; }
    { const char * tb_v14047 = "    if (TB_CPU_DRAW) tb_put(x, y, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v14047; }
    { const char * tb_v14048 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14048; }
    { const char * tb_v14049 = "// полупрозрачный цвет (rgba): в старшем байте — прозрачность 1..255 (0 — непрозрачный, как у rgb).\n"; *(const char * *)tb_grow(v_lines) = tb_v14049; }
    { const char * tb_v14050 = "// Смешивание как у видеокарты: округл(цвет * a / 255) + округл(фон * (255 - a) / 255), a = 255 − прозрачность;\n"; *(const char * *)tb_grow(v_lines) = tb_v14050; }
    { const char * tb_v14051 = "// в TB_GPU_CHECK — по таблице пробы (tb_blend_lut), тогда кадры совпадают точка в точку\n"; *(const char * *)tb_grow(v_lines) = tb_v14051; }
    { const char * tb_v14052 = "TB_INL uint32_t tb_mix_a(uint32_t d, uint32_t c, uint32_t a) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14052; }
    { const char * tb_v14053 = "    if (a >= 255) return c & 0xFFFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v14053; }
    { const char * tb_v14054 = "    if (a == 0) return d & 0xFFFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v14054; }
    { const char * tb_v14055 = "    uint32_t r = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14055; }
    { const char * tb_v14056 = "    for (int sh = 0; sh <= 16; sh += 8) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14056; }
    { const char * tb_v14057 = "        uint32_t sc = (c >> sh) & 255, dc = (d >> sh) & 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v14057; }
    { const char * tb_v14058 = "        uint32_t q = tb_blend_cal ? tb_blend_lut[(sc << 16) | (dc << 8) | a] : (sc * a + 127) / 255 + (dc * (255 - a) + 127) / 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v14058; }
    { const char * tb_v14059 = "        r |= (q > 255 ? 255 : q) << sh;\n"; *(const char * *)tb_grow(v_lines) = tb_v14059; }
    { const char * tb_v14060 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v14060; }
    { const char * tb_v14061 = "    return r;\n"; *(const char * *)tb_grow(v_lines) = tb_v14061; }
    { const char * tb_v14062 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14062; }
    { const char * tb_v14063 = "TB_INL uint32_t tb_mix(uint32_t d, uint32_t c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14063; }
    { const char * tb_v14064 = "    return tb_mix_a(d, c, 255 - ((c >> 24) & 255));\n"; *(const char * *)tb_grow(v_lines) = tb_v14064; }
    { const char * tb_v14065 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14065; }
    { const char * tb_v14066 = "TB_API void tb_cpu_rect(long long x, long long y, long long w, long long h, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14066; }
    { const char * tb_v14067 = "    long long x0 = x < 0 ? 0 : x, y0 = y < 0 ? 0 : y, x1 = x + w > tb_gw ? tb_gw : x + w, y1 = y + h > tb_gh ? tb_gh : y + h;\n"; *(const char * *)tb_grow(v_lines) = tb_v14067; }
    { const char * tb_v14068 = "    if ((c >> 24) & 255) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14068; }
    { const char * tb_v14069 = "        for (long long j = y0; j < y1; j++) for (long long i = x0; i < x1; i++) tb_px[j * tb_gw + i] = tb_mix(tb_px[j * tb_gw + i], (uint32_t)c);\n"; *(const char * *)tb_grow(v_lines) = tb_v14069; }
    { const char * tb_v14070 = "        return;\n"; *(const char * *)tb_grow(v_lines) = tb_v14070; }
    { const char * tb_v14071 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v14071; }
    { const char * tb_v14072 = "    for (long long j = y0; j < y1; j++) for (long long i = x0; i < x1; i++) tb_px[j * tb_gw + i] = (uint32_t)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v14072; }
    { const char * tb_v14073 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14073; }
    { const char * tb_v14074 = "TB_API void tb_draw_rect(long long x, long long y, long long w, long long h, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14074; }
    { const char * tb_v14075 = "    TB_SCENE();\n"; *(const char * *)tb_grow(v_lines) = tb_v14075; }
    { const char * tb_v14076 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v14076; }
    { const char * tb_v14077 = "    if (tb_gpu_on) tb_gpu_rect(x, y, w, h, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v14077; }
    { const char * tb_v14078 = "    if (TB_CPU_DRAW) tb_cpu_rect(x, y, w, h, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v14078; }
    { const char * tb_v14079 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14079; }
    { const char * tb_v14080 = "// точка (i, j) с прозрачностью a (0..255) цвета c\n"; *(const char * *)tb_grow(v_lines) = tb_v14080; }
    { const char * tb_v14081 = "TB_INL void tb_put_a(long long i, long long j, uint32_t c, uint32_t a) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14081; }
    { const char * tb_v14082 = "    if (i < 0 || j < 0 || i >= tb_gw || j >= tb_gh || a == 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v14082; }
    { const char * tb_v14083 = "    uint32_t *p = &tb_px[j * tb_gw + i];\n"; *(const char * *)tb_grow(v_lines) = tb_v14083; }
    { const char * tb_v14084 = "    *p = tb_mix_a(*p, c, a);\n"; *(const char * *)tb_grow(v_lines) = tb_v14084; }
    { const char * tb_v14085 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14085; }
    { const char * tb_v14086 = "// целый корень floor(sqrt(n)) — одинаково на процессоре и в шейдере\n"; *(const char * *)tb_grow(v_lines) = tb_v14086; }
    { const char * tb_v14087 = "TB_INL uint32_t tb_isqrt(uint32_t n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14087; }
    { const char * tb_v14088 = "    uint32_t s = (uint32_t)sqrt((double)n);\n"; *(const char * *)tb_grow(v_lines) = tb_v14088; }
    { const char * tb_v14089 = "    while (s * s > n) s--;\n"; *(const char * *)tb_grow(v_lines) = tb_v14089; }
    { const char * tb_v14090 = "    while ((s + 1) * (s + 1) <= n) s++;\n"; *(const char * *)tb_grow(v_lines) = tb_v14090; }
    { const char * tb_v14091 = "    return s;\n"; *(const char * *)tb_grow(v_lines) = tb_v14091; }
    { const char * tb_v14092 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14092; }
    { const char * tb_v14093 = "// сглаженный угол: q = (2·dx)² + (2·dy)² от центра угла до середины точки, радиус r ≤ 255.\n"; *(const char * *)tb_grow(v_lines) = tb_v14093; }
    { const char * tb_v14094 = "// Покрытие 0..255 = (r + 0.5 − расстояние), целыми числами (так же считает шейдер)\n"; *(const char * *)tb_grow(v_lines) = tb_v14094; }
    { const char * tb_v14095 = "TB_INL uint32_t tb_round_cov(uint32_t q, long long r) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14095; }
    { const char * tb_v14096 = "    long long lo = 2 * r - 1, hi = 2 * r + 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14096; }
    { const char * tb_v14097 = "    if (lo >= 0 && q <= (uint32_t)(lo * lo)) return 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v14097; }
    { const char * tb_v14098 = "    if (q >= (uint32_t)(hi * hi)) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14098; }
    { const char * tb_v14099 = "    long long v = (2 * r + 1) * 64 - (long long)tb_isqrt(q * 4096u);   // 128 · (r + 0.5 − расстояние)\n"; *(const char * *)tb_grow(v_lines) = tb_v14099; }
    { const char * tb_v14100 = "    if (v < 0) v = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14100; }
    { const char * tb_v14101 = "    v = (v * 255 + 64) / 128;\n"; *(const char * *)tb_grow(v_lines) = tb_v14101; }
    { const char * tb_v14102 = "    return v > 255 ? 255 : (uint32_t)v;\n"; *(const char * *)tb_grow(v_lines) = tb_v14102; }
    { const char * tb_v14103 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14103; }
    { const char * tb_v14104 = "// тень: внутри радиуса r — вся (ca), дальше к r + size сходит на нет по квадрату; r + size ≤ 255\n"; *(const char * *)tb_grow(v_lines) = tb_v14104; }
    { const char * tb_v14105 = "TB_INL uint32_t tb_shadow_a(uint32_t q, long long r, long long size, uint32_t ca) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14105; }
    { const char * tb_v14106 = "    if (q <= (uint32_t)(4 * r * r)) return ca;\n"; *(const char * *)tb_grow(v_lines) = tb_v14106; }
    { const char * tb_v14107 = "    if (q >= (uint32_t)(4 * (r + size) * (r + size))) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14107; }
    { const char * tb_v14108 = "    long long g = ((r + size) * 128 - (long long)tb_isqrt(q * 4096u)) >> 3;   // осталось до края, в 1/16 точки\n"; *(const char * *)tb_grow(v_lines) = tb_v14108; }
    { const char * tb_v14109 = "    uint32_t S = (uint32_t)(size * 16);\n"; *(const char * *)tb_grow(v_lines) = tb_v14109; }
    { const char * tb_v14110 = "    if (g < 0) g = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14110; }
    { const char * tb_v14111 = "    if (g > (long long)S) g = S;\n"; *(const char * *)tb_grow(v_lines) = tb_v14111; }
    { const char * tb_v14112 = "    return (ca * (uint32_t)g * (uint32_t)g + S * S / 2) / (S * S);\n"; *(const char * *)tb_grow(v_lines) = tb_v14112; }
    { const char * tb_v14113 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14113; }
    { const char * tb_v14114 = "// угол-квадрат x0..x1, y0..y1 с центром (ox, oy): сглаженный (shadow = 0) или угол тени\n"; *(const char * *)tb_grow(v_lines) = tb_v14114; }
    { const char * tb_v14115 = "TB_API void tb_soft_corner(long long x0, long long y0, long long x1, long long y1, long long ox, long long oy, long long r, long long size, long long c, int shadow) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14115; }
    { const char * tb_v14116 = "    if (x0 >= x1 || y0 >= y1) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v14116; }
    { const char * tb_v14117 = "    if (tb_gpu_on) tb_gpu_soft(x0, y0, x1, y1, ox, oy, c, shadow ? (1u << 28) | ((uint32_t)size << 11) | (uint32_t)r : (1u << 29) | (uint32_t)r);\n"; *(const char * *)tb_grow(v_lines) = tb_v14117; }
    { const char * tb_v14118 = "    if (!TB_CPU_DRAW) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v14118; }
    { const char * tb_v14119 = "    uint32_t ca = 255 - (((uint32_t)c >> 24) & 255);\n"; *(const char * *)tb_grow(v_lines) = tb_v14119; }
    { const char * tb_v14120 = "    long long ja = y0 < 0 ? 0 : y0, jb = y1 > tb_gh ? tb_gh : y1, ia = x0 < 0 ? 0 : x0, ib = x1 > tb_gw ? tb_gw : x1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14120; }
    { const char * tb_v14121 = "    for (long long j = ja; j < jb; j++) for (long long i = ia; i < ib; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14121; }
    { const char * tb_v14122 = "        long long dx = 2 * (i - ox) + 1, dy = 2 * (j - oy) + 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14122; }
    { const char * tb_v14123 = "        uint32_t q = (uint32_t)(dx * dx + dy * dy), a;\n"; *(const char * *)tb_grow(v_lines) = tb_v14123; }
    { const char * tb_v14124 = "        if (shadow) a = tb_shadow_a(q, r, size, ca);\n"; *(const char * *)tb_grow(v_lines) = tb_v14124; }
    { const char * tb_v14125 = "        else a = (tb_round_cov(q, r) * ca + 127) / 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v14125; }
    { const char * tb_v14126 = "        tb_put_a(i, j, (uint32_t)c, a);\n"; *(const char * *)tb_grow(v_lines) = tb_v14126; }
    { const char * tb_v14127 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v14127; }
    { const char * tb_v14128 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14128; }
    { const char * tb_v14129 = "// draw_shadow(x, y, w, h, r, size, c): мягкая тень скруглённого прямоугольника — внутри цвет c,\n"; *(const char * *)tb_grow(v_lines) = tb_v14129; }
    { const char * tb_v14130 = "// снаружи к size точкам сходит на нет. Точки делятся на куски без наложений: середина — сплошняком,\n"; *(const char * *)tb_grow(v_lines) = tb_v14130; }
    { const char * tb_v14131 = "// полосы вдоль сторон — по строке/столбцу одной прозрачности, углы — по кругу (tb_soft_corner).\n"; *(const char * *)tb_grow(v_lines) = tb_v14131; }
    { const char * tb_v14132 = "// Всё целыми числами, поэтому видеокарта рисует то же самое точка в точку\n"; *(const char * *)tb_grow(v_lines) = tb_v14132; }
    { const char * tb_v14133 = "TB_API void tb_draw_shadow(long long x, long long y, long long w, long long h, long long r, long long size, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14133; }
    { const char * tb_v14134 = "    TB_SCENE();\n"; *(const char * *)tb_grow(v_lines) = tb_v14134; }
    { const char * tb_v14135 = "    if (!tb_px || w <= 0 || h <= 0 || size <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v14135; }
    { const char * tb_v14136 = "    if (r * 2 > w) r = w / 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v14136; }
    { const char * tb_v14137 = "    if (r * 2 > h) r = h / 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v14137; }
    { const char * tb_v14138 = "    if (r < 0) r = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14138; }
    { const char * tb_v14139 = "    if (r > 127) r = 127;\n"; *(const char * *)tb_grow(v_lines) = tb_v14139; }
    { const char * tb_v14140 = "    if (size > 255 - r) size = 255 - r;\n"; *(const char * *)tb_grow(v_lines) = tb_v14140; }
    { const char * tb_v14141 = "    uint32_t ca = 255 - (((uint32_t)c >> 24) & 255), rgb = (uint32_t)c & 0xFFFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v14141; }
    { const char * tb_v14142 = "    // середина\n"; *(const char * *)tb_grow(v_lines) = tb_v14142; }
    { const char * tb_v14143 = "    tb_draw_rect(x, y + r, w, h - 2 * r, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v14143; }
    { const char * tb_v14144 = "    tb_draw_rect(x + r, y, w - 2 * r, r, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v14144; }
    { const char * tb_v14145 = "    tb_draw_rect(x + r, y + h - r, w - 2 * r, r, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v14145; }
    { const char * tb_v14146 = "    // полосы вдоль сторон: k-я строка/столбец от края\n"; *(const char * *)tb_grow(v_lines) = tb_v14146; }
    { const char * tb_v14147 = "    for (long long k = 0; k < size; k++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14147; }
    { const char * tb_v14148 = "        uint32_t q = (uint32_t)((2 * k + 1) * (2 * k + 1)), a = tb_shadow_a(q, 0, size, ca);\n"; *(const char * *)tb_grow(v_lines) = tb_v14148; }
    { const char * tb_v14149 = "        if (a == 0) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v14149; }
    { const char * tb_v14150 = "        long long cc = (long long)(((255 - a) << 24) | rgb);\n"; *(const char * *)tb_grow(v_lines) = tb_v14150; }
    { const char * tb_v14151 = "        tb_draw_rect(x + r, y - 1 - k, w - 2 * r, 1, cc);\n"; *(const char * *)tb_grow(v_lines) = tb_v14151; }
    { const char * tb_v14152 = "        tb_draw_rect(x + r, y + h + k, w - 2 * r, 1, cc);\n"; *(const char * *)tb_grow(v_lines) = tb_v14152; }
    { const char * tb_v14153 = "        tb_draw_rect(x - 1 - k, y + r, 1, h - 2 * r, cc);\n"; *(const char * *)tb_grow(v_lines) = tb_v14153; }
    { const char * tb_v14154 = "        tb_draw_rect(x + w + k, y + r, 1, h - 2 * r, cc);\n"; *(const char * *)tb_grow(v_lines) = tb_v14154; }
    { const char * tb_v14155 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v14155; }
    { const char * tb_v14156 = "    // углы\n"; *(const char * *)tb_grow(v_lines) = tb_v14156; }
    { const char * tb_v14157 = "    tb_soft_corner(x - size, y - size, x + r, y + r, x + r, y + r, r, size, c, 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v14157; }
    { const char * tb_v14158 = "    tb_soft_corner(x + w - r, y - size, x + w + size, y + r, x + w - r, y + r, r, size, c, 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v14158; }
    { const char * tb_v14159 = "    tb_soft_corner(x - size, y + h - r, x + r, y + h + size, x + r, y + h - r, r, size, c, 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v14159; }
    { const char * tb_v14160 = "    tb_soft_corner(x + w - r, y + h - r, x + w + size, y + h + size, x + w - r, y + h - r, r, size, c, 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v14160; }
    { const char * tb_v14161 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14161; }
    { const char * tb_v14162 = "// скругление углов: \"\" или \"all\" — все; иначе слова top bottom left right tl tr bl br через пробел\n"; *(const char * *)tb_grow(v_lines) = tb_v14162; }
    { const char * tb_v14163 = "TB_API int tb_corners(const char *s) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14163; }
    { const char * tb_v14164 = "    if (!s || !*s) return 15;\n"; *(const char * *)tb_grow(v_lines) = tb_v14164; }
    { const char * tb_v14165 = "    int m = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14165; }
    { const char * tb_v14166 = "    const char *w[] = { \"all\", \"top\", \"bottom\", \"left\", \"right\", \"tl\", \"tr\", \"bl\", \"br\" };\n"; *(const char * *)tb_grow(v_lines) = tb_v14166; }
    { const char * tb_v14167 = "    const int v[] = { 15, 3, 12, 5, 10, 1, 2, 4, 8 };\n"; *(const char * *)tb_grow(v_lines) = tb_v14167; }
    { const char * tb_v14168 = "    while (*s) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14168; }
    { const char * tb_v14169 = "        while (*s == ' ' || *s == ',') s++;\n"; *(const char * *)tb_grow(v_lines) = tb_v14169; }
    { const char * tb_v14170 = "        const char *e = s;\n"; *(const char * *)tb_grow(v_lines) = tb_v14170; }
    { const char * tb_v14171 = "        while (*e && *e != ' ' && *e != ',') e++;\n"; *(const char * *)tb_grow(v_lines) = tb_v14171; }
    { const char * tb_v14172 = "        for (int i = 0; i < 9; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v14172; }
    { const char * tb_v14173 = "            if ((size_t)(e - s) == strlen(w[i]) && strncmp(s, w[i], (size_t)(e - s)) == 0) m |= v[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v14173; }
    { const char * tb_v14174 = "        s = e;\n"; *(const char * *)tb_grow(v_lines) = tb_v14174; }
    { const char * tb_v14175 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v14175; }
    { const char * tb_v14176 = "    return m;\n"; *(const char * *)tb_grow(v_lines) = tb_v14176; }
    { const char * tb_v14177 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14177; }
    { const char * tb_v14178 = "// прямоугольник со скруглёнными углами, края сглажены; цвет может быть полупрозрачным (rgba).\n"; *(const char * *)tb_grow(v_lines) = tb_v14178; }
    { const char * tb_v14179 = "// Куски без наложений: середина и боковые полосы — прямоугольники, углы — сглаженные квадраты r×r\n"; *(const char * *)tb_grow(v_lines) = tb_v14179; }
    { const char * tb_v14180 = "// (tb_soft_corner): процессор и видеокарта считают покрытие одной целой формулой\n"; *(const char * *)tb_grow(v_lines) = tb_v14180; }
    { const char * tb_v14181 = "TB_API void tb_draw_round(long long x, long long y, long long w, long long h, long long r, const char *corners, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14181; }
    { const char * tb_v14182 = "    TB_SCENE();\n"; *(const char * *)tb_grow(v_lines) = tb_v14182; }
    { const char * tb_v14183 = "    if (!tb_px || w <= 0 || h <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v14183; }
    { const char * tb_v14184 = "    int m = tb_corners(corners);\n"; *(const char * *)tb_grow(v_lines) = tb_v14184; }
    { const char * tb_v14185 = "    if (r < 0) r = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14185; }
    { const char * tb_v14186 = "    if (r * 2 > w) r = w / 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v14186; }
    { const char * tb_v14187 = "    if (r * 2 > h) r = h / 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v14187; }
    { const char * tb_v14188 = "    if (r > 255) r = 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v14188; }
    { const char * tb_v14189 = "    if (r == 0) { tb_draw_rect(x, y, w, h, c); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v14189; }
    { const char * tb_v14190 = "    tb_draw_rect(x + r, y, w - 2 * r, h, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v14190; }
    { const char * tb_v14191 = "    tb_draw_rect(x, y + r, r, h - 2 * r, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v14191; }
    { const char * tb_v14192 = "    tb_draw_rect(x + w - r, y + r, r, h - 2 * r, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v14192; }
    { const char * tb_v14193 = "    long long cx[4] = { x, x + w - r, x, x + w - r }, cy[4] = { y, y, y + h - r, y + h - r };\n"; *(const char * *)tb_grow(v_lines) = tb_v14193; }
    { const char * tb_v14194 = "    long long ox[4] = { x + r, x + w - r, x + r, x + w - r }, oy[4] = { y + r, y + r, y + h - r, y + h - r };\n"; *(const char * *)tb_grow(v_lines) = tb_v14194; }
    { const char * tb_v14195 = "    for (int k = 0; k < 4; k++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14195; }
    { const char * tb_v14196 = "        if (m & (1 << k)) tb_soft_corner(cx[k], cy[k], cx[k] + r, cy[k] + r, ox[k], oy[k], r, 0, c, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v14196; }
    { const char * tb_v14197 = "        else tb_draw_rect(cx[k], cy[k], r, r, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v14197; }
    { const char * tb_v14198 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v14198; }
    { const char * tb_v14199 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14199; }
    { const char * tb_v14200 = "// размыть то, что уже нарисовано в прямоугольнике (матовое стекло, мягкий фон): три прохода «ящиком»\n"; *(const char * *)tb_grow(v_lines) = tb_v14200; }
    { const char * tb_v14201 = "// размытие одного ряда (n точек с шагом step в буфере b) скользящей суммой окна 2r+1; tmp — n точек\n"; *(const char * *)tb_grow(v_lines) = tb_v14201; }
    { const char * tb_v14202 = "TB_INL void tb_blur_run(uint32_t *b, long long n, long long step, long long r, uint32_t *tmp) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14202; }
    { const char * tb_v14203 = "    for (long long k = 0; k < n; k++) tmp[k] = b[k * step];\n"; *(const char * *)tb_grow(v_lines) = tb_v14203; }
    { const char * tb_v14204 = "    long long win = 2 * r + 1, sr = 0, sg = 0, sb = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14204; }
    { const char * tb_v14205 = "    uint64_t mul = (uint64_t)(((1u << 24) + win / 2) / win);   // деление — умножением (оно в десятки раз быстрее)\n"; *(const char * *)tb_grow(v_lines) = tb_v14205; }
    { const char * tb_v14206 = "    for (long long k = -r; k <= r; k++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14206; }
    { const char * tb_v14207 = "        uint32_t v = tmp[k < 0 ? 0 : k >= n ? n - 1 : k];\n"; *(const char * *)tb_grow(v_lines) = tb_v14207; }
    { const char * tb_v14208 = "        sr += (v >> 16) & 255; sg += (v >> 8) & 255; sb += v & 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v14208; }
    { const char * tb_v14209 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v14209; }
    { const char * tb_v14210 = "    for (long long k = 0; k < n; k++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14210; }
    { const char * tb_v14211 = "        uint64_t vr = ((uint64_t)sr * mul + (1u << 23)) >> 24, vg = ((uint64_t)sg * mul + (1u << 23)) >> 24, vb = ((uint64_t)sb * mul + (1u << 23)) >> 24;\n"; *(const char * *)tb_grow(v_lines) = tb_v14211; }
    { const char * tb_v14212 = "        b[k * step] = (uint32_t)((vr > 255 ? 255 : vr) << 16 | (vg > 255 ? 255 : vg) << 8 | (vb > 255 ? 255 : vb));\n"; *(const char * *)tb_grow(v_lines) = tb_v14212; }
    { const char * tb_v14213 = "        uint32_t out = tmp[k - r < 0 ? 0 : k - r], in = tmp[k + r + 1 >= n ? n - 1 : k + r + 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v14213; }
    { const char * tb_v14214 = "        sr += (long long)((in >> 16) & 255) - ((out >> 16) & 255);\n"; *(const char * *)tb_grow(v_lines) = tb_v14214; }
    { const char * tb_v14215 = "        sg += (long long)((in >> 8) & 255) - ((out >> 8) & 255);\n"; *(const char * *)tb_grow(v_lines) = tb_v14215; }
    { const char * tb_v14216 = "        sb += (long long)(in & 255) - (out & 255);\n"; *(const char * *)tb_grow(v_lines) = tb_v14216; }
    { const char * tb_v14217 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v14217; }
    { const char * tb_v14218 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14218; }
    { const char * tb_v14219 = "// матовое стекло: размытие прямоугольника кадра. Большое размытие (r >= 4) считается на картинке\n"; *(const char * *)tb_grow(v_lines) = tb_v14219; }
    { const char * tb_v14220 = "// вдвое меньше (в 4 раза меньше точек), потом плавно растягивается обратно — на глаз то же самое.\n"; *(const char * *)tb_grow(v_lines) = tb_v14220; }
    { const char * tb_v14221 = "TB_API void tb_blur_rect(long long x, long long y, long long w, long long h, long long r) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14221; }
    { const char * tb_v14222 = "    TB_SCENE();\n"; *(const char * *)tb_grow(v_lines) = tb_v14222; }
    { const char * tb_v14223 = "    if (!tb_px || r <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v14223; }
    { const char * tb_v14224 = "    long long x0 = x < 0 ? 0 : x, y0 = y < 0 ? 0 : y, x1 = x + w > tb_gw ? tb_gw : x + w, y1 = y + h > tb_gh ? tb_gh : y + h;\n"; *(const char * *)tb_grow(v_lines) = tb_v14224; }
    { const char * tb_v14225 = "    long long W = x1 - x0, H = y1 - y0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14225; }
    { const char * tb_v14226 = "    if (W <= 1 || H <= 1) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v14226; }
    { const char * tb_v14227 = "    int half = r >= 4 && W >= 8 && H >= 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v14227; }
    { const char * tb_v14228 = "    long long bw = half ? (W + 1) / 2 : W, bh = half ? (H + 1) / 2 : H, br = half ? r / 2 : r;\n"; *(const char * *)tb_grow(v_lines) = tb_v14228; }
    { const char * tb_v14229 = "    uint32_t *b = malloc((size_t)(bw * bh + (bw > bh ? bw : bh)) * 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v14229; }
    { const char * tb_v14230 = "    if (!b) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v14230; }
    { const char * tb_v14231 = "    uint32_t *tmp = b + bw * bh;\n"; *(const char * *)tb_grow(v_lines) = tb_v14231; }
