    { const char * tb_v14254 = "                long long ix = fx >> 8, tx = fx & 255, ix2 = ix + 1 < bw ? ix + 1 : ix;\n"; *(const char * *)tb_grow(v_lines) = tb_v14254; }
    { const char * tb_v14255 = "                uint32_t p = b[iy * bw + ix], q = b[iy * bw + ix2], u = b[iy2 * bw + ix], v = b[iy2 * bw + ix2], o = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14255; }
    { const char * tb_v14256 = "                for (int sh = 0; sh <= 16; sh += 8) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14256; }
    { const char * tb_v14257 = "                    long long a = (p >> sh & 255) * (256 - tx) + (q >> sh & 255) * tx, c = (u >> sh & 255) * (256 - tx) + (v >> sh & 255) * tx;\n"; *(const char * *)tb_grow(v_lines) = tb_v14257; }
    { const char * tb_v14258 = "                    o |= (uint32_t)(((a * (256 - ty) + c * ty + 32768) >> 16) & 255) << sh;\n"; *(const char * *)tb_grow(v_lines) = tb_v14258; }
    { const char * tb_v14259 = "                }\n"; *(const char * *)tb_grow(v_lines) = tb_v14259; }
    { const char * tb_v14260 = "                tb_px[(y0 + yy) * tb_gw + x0 + xx] = o;\n"; *(const char * *)tb_grow(v_lines) = tb_v14260; }
    { const char * tb_v14261 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v14261; }
    { const char * tb_v14262 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v14262; }
    { const char * tb_v14263 = "    else\n"; *(const char * *)tb_grow(v_lines) = tb_v14263; }
    { const char * tb_v14264 = "        for (long long yy = 0; yy < bh; yy++) memcpy(tb_px + (y0 + yy) * tb_gw + x0, b + yy * bw, (size_t)bw * 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v14264; }
    { const char * tb_v14265 = "    free(b);\n"; *(const char * *)tb_grow(v_lines) = tb_v14265; }
    { const char * tb_v14266 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14266; }
    { const char * tb_v14267 = "TB_API void tb_draw_circle(long long cx, long long cy, long long r, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14267; }
    { const char * tb_v14268 = "    TB_SCENE();\n"; *(const char * *)tb_grow(v_lines) = tb_v14268; }
    { const char * tb_v14269 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v14269; }
    { const char * tb_v14270 = "    if (tb_gpu_on) tb_gpu_circle(cx, cy, r, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v14270; }
    { const char * tb_v14271 = "    if (TB_CPU_DRAW) {   // только строки и столбцы внутри окна: огромный круг не перебирает r*r точек\n"; *(const char * *)tb_grow(v_lines) = tb_v14271; }
    { const char * tb_v14272 = "        long long ja = -r > -cy ? -r : -cy, jb = r < tb_gh - 1 - cy ? r : tb_gh - 1 - cy;\n"; *(const char * *)tb_grow(v_lines) = tb_v14272; }
    { const char * tb_v14273 = "        long long ia = -r > -cx ? -r : -cx, ib = r < tb_gw - 1 - cx ? r : tb_gw - 1 - cx;\n"; *(const char * *)tb_grow(v_lines) = tb_v14273; }
    { const char * tb_v14274 = "        for (long long j = ja; j <= jb; j++) for (long long i = ia; i <= ib; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v14274; }
