    { const char * tb_v14278 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v14278; }
    { const char * tb_v14279 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v14279; }
    { const char * tb_v14280 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14280; }
    { const char * tb_v14281 = "TB_API void tb_draw_line(long long x0, long long y0, long long x1, long long y1, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14281; }
    { const char * tb_v14282 = "    TB_SCENE();\n"; *(const char * *)tb_grow(v_lines) = tb_v14282; }
    { const char * tb_v14283 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v14283; }
    { const char * tb_v14284 = "    long long dx = x1 > x0 ? x1 - x0 : x0 - x1, dy = y1 > y0 ? y0 - y1 : y1 - y0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14284; }
    { const char * tb_v14285 = "    long long sx = x0 < x1 ? 1 : -1, sy = y0 < y1 ? 1 : -1, e = dx + dy;\n"; *(const char * *)tb_grow(v_lines) = tb_v14285; }
    { const char * tb_v14286 = "    int gpu = tb_gpu_on, cpu = TB_CPU_DRAW;\n"; *(const char * *)tb_grow(v_lines) = tb_v14286; }
    { const char * tb_v14287 = "    while (1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14287; }
    { const char * tb_v14288 = "        if (gpu) tb_gpu_rect(x0, y0, 1, 1, c & 0xFFFFFF);   // соседние точки склеятся в полоски\n"; *(const char * *)tb_grow(v_lines) = tb_v14288; }
    { const char * tb_v14289 = "        if (cpu) tb_put(x0, y0, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v14289; }
