    { const char * tb_v14484 = "    long long cx = x;\n"; *(const char * *)tb_grow(v_lines) = tb_v14484; }
    { const char * tb_v14485 = "    while (*p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14485; }
    { const char * tb_v14486 = "        unsigned int u = *p++;\n"; *(const char * *)tb_grow(v_lines) = tb_v14486; }
    { const char * tb_v14487 = "        if (u >= 0x80) {   // UTF-8: собрать букву из 2–4 байт\n"; *(const char * *)tb_grow(v_lines) = tb_v14487; }
    { const char * tb_v14488 = "            int more = u >= 0xF0 ? 3 : u >= 0xE0 ? 2 : u >= 0xC0 ? 1 : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14488; }
    { const char * tb_v14489 = "            u &= 0x3F >> more;\n"; *(const char * *)tb_grow(v_lines) = tb_v14489; }
    { const char * tb_v14490 = "            while (more-- > 0 && (*p & 0xC0) == 0x80) u = (u << 6) | (*p++ & 0x3F);\n"; *(const char * *)tb_grow(v_lines) = tb_v14490; }
    { const char * tb_v14491 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v14491; }
    { const char * tb_v14492 = "        if (u == 0x2013 || u == 0x2014) u = '-';\n"; *(const char * *)tb_grow(v_lines) = tb_v14492; }
    { const char * tb_v14493 = "        if (u == 0xD7) u = 'x';   // × как x (размер окна 640×400)\n"; *(const char * *)tb_grow(v_lines) = tb_v14493; }
    { const char * tb_v14494 = "        if (u == 0xAB || u == 0xBB || u == 0x201C || u == 0x201D) u = '\"';\n"; *(const char * *)tb_grow(v_lines) = tb_v14494; }
    { const char * tb_v14495 = "        if (u == '\\n') { cx = x; y += 16 * size; continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v14495; }
    { const char * tb_v14496 = "        int g = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14496; }
    { const char * tb_v14497 = "        if (u >= 32 && u <= 126) g = (int)u - 32;\n"; *(const char * *)tb_grow(v_lines) = tb_v14497; }
    { const char * tb_v14498 = "        else if (u >= 0x410 && u <= 0x44F) g = 95 + (int)(u - 0x410);\n"; *(const char * *)tb_grow(v_lines) = tb_v14498; }
    { const char * tb_v14499 = "        else if (u == 0x401) g = 159;\n"; *(const char * *)tb_grow(v_lines) = tb_v14499; }
    { const char * tb_v14500 = "        else if (u == 0x451) g = 160;\n"; *(const char * *)tb_grow(v_lines) = tb_v14500; }
    { const char * tb_v14501 = "        if (g < 0) g = '?' - 32;\n"; *(const char * *)tb_grow(v_lines) = tb_v14501; }
    { const char * tb_v14502 = "        if (tb_gpu_on && g != 0) tb_gpu_glyph(cx, y, g, size, c);   // 0 — пробел, рисовать нечего\n"; *(const char * *)tb_grow(v_lines) = tb_v14502; }
    { const char * tb_v14503 = "        if (TB_CPU_DRAW)\n"; *(const char * *)tb_grow(v_lines) = tb_v14503; }
    { const char * tb_v14504 = "            for (int row = 0; row < 16; row++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14504; }
    { const char * tb_v14505 = "                unsigned char bits = tb_font[g][row];\n"; *(const char * *)tb_grow(v_lines) = tb_v14505; }
    { const char * tb_v14506 = "                for (int col = 0; col < 8; col++)\n"; *(const char * *)tb_grow(v_lines) = tb_v14506; }
    { const char * tb_v14507 = "                    if (bits & (0x80 >> col)) tb_cpu_rect(cx + col * size, y + row * size, size, size, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v14507; }
    { const char * tb_v14508 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v14508; }
    { const char * tb_v14509 = "        cx += 8 * size;\n"; *(const char * *)tb_grow(v_lines) = tb_v14509; }
