    { const char * tb_v14533 = "    int shp, shc, shok; float shv[16]; int shimg[4]; int noshadow; float *shvd; long long shvn, shvcap, shused; void *shvb;\n"; *(const char * *)tb_grow(v_lines) = tb_v14533; }
    { const char * tb_v14534 = "    long long lod; double lodd, far, ub[4]; int hasub; } tb_mesh;   // lod — сетка вместо этой дальше lodd; far — дальше не рисовать; ub — свой шар (mesh_bounds)   // gpu func: шейдер точки и углов (-1 — обычный), настройки, углы для видеокарты     // кости и у каждого угла до 4 костей с весами   // куски: chr — (первый треугольник, сколько), chs и bs — шары (центр, радиус)\n"; *(const char * *)tb_grow(v_lines) = tb_v14534; }
    { const char * tb_v14535 = "TB_API tb_mesh *tb_meshes = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14535; }
    { const char * tb_v14536 = "TB_API long long tb_nmesh = 0, tb_capmesh = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14536; }
    { const char * tb_v14537 = "TB_API double tb_cam[9] = { 0, 0, -5,  1, 0, 0,  0, 1, 0 };   // где камера, вправо, вверх\n"; *(const char * *)tb_grow(v_lines) = tb_v14537; }
