    { const char * tb_v14539 = "TB_API long long *tb_mfree = 0, tb_nmfree = 0, tb_capmfree = 0;   // номера сеток после mesh_free: mesh_new берёт их снова\n"; *(const char * *)tb_grow(v_lines) = tb_v14539; }
