    { const char * tb_v14675 = "TB_API double tb_amb0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14675; }
    { const char * tb_v14676 = "TB_API void tb_light(double dx, double dy, double dz, double amb) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14676; }
    { const char * tb_v14677 = "    TB_SCENE();\n"; *(const char * *)tb_grow(v_lines) = tb_v14677; }
