    { const char * tb_v14686 = "// нормали треугольников: (b - a) × (c - a), длина 2^14. У куба, где грани по кругу против часовой\n"; *(const char * *)tb_grow(v_lines) = tb_v14686; }
    { const char * tb_v14687 = "// стрелки снаружи, нормаль смотрит наружу\n"; *(const char * *)tb_grow(v_lines) = tb_v14687; }
    { const char * tb_v14688 = "static void tb_mesh_normals(tb_mesh *m) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14688; }
    { const char * tb_v14689 = "    if (m->nrmok) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v14689; }
    { const char * tb_v14690 = "    m->nrmok = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14690; }
    { const char * tb_v14691 = "    if (m->nrmcap < m->n) { m->nrmcap = m->cap; m->nrm = (int32_t *)realloc(m->nrm, sizeof(int32_t) * 3 * (size_t)m->nrmcap); }\n"; *(const char * *)tb_grow(v_lines) = tb_v14691; }
