    { const char * tb_v14701 = "// (со спины свет считается от обратной стороны: у пола и листа обе стороны освещены честно)\n"; *(const char * *)tb_grow(v_lines) = tb_v14701; }
    { const char * tb_v14702 = "TB_INL uint32_t tb_shade(uint32_t c, const int32_t *n, const int32_t *L, int front) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14702; }
    { const char * tb_v14703 = "    if (L[3] < 0) return c;\n"; *(const char * *)tb_grow(v_lines) = tb_v14703; }
    { const char * tb_v14704 = "    int s = n[0] * L[0] + n[1] * L[1] + n[2] * L[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v14704; }
    { const char * tb_v14705 = "    if (!front) s = -s;\n"; *(const char * *)tb_grow(v_lines) = tb_v14705; }
    { const char * tb_v14706 = "    if (s < 0) s = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14706; }
    { const char * tb_v14707 = "    int k = L[3] + (((256 - L[3]) * (s >> 14)) >> 14);\n"; *(const char * *)tb_grow(v_lines) = tb_v14707; }
    { const char * tb_v14708 = "    uint32_t r = (((c >> 16) & 255) * (uint32_t)k + 128) >> 8, g = (((c >> 8) & 255) * (uint32_t)k + 128) >> 8, b = ((c & 255) * (uint32_t)k + 128) >> 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v14708; }
    { const char * tb_v14709 = "    return (c & 0xFF000000u) | (r << 16) | (g << 8) | b;\n"; *(const char * *)tb_grow(v_lines) = tb_v14709; }
    { const char * tb_v14710 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14710; }
    { const char * tb_v14711 = "// плоскость глубины по трём точкам экрана (x, y, D); 0 — треугольник ребром к нам, рисовать нечего\n"; *(const char * *)tb_grow(v_lines) = tb_v14711; }
    { const char * tb_v14712 = "TB_INL int tb_tri3_plane(const double *sx, const double *sy, const double *dd, uint32_t *pl) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14712; }
    { const char * tb_v14713 = "    double e1x = sx[1] - sx[0], e1y = sy[1] - sy[0], e2x = sx[2] - sx[0], e2y = sy[2] - sy[0];\n"; *(const char * *)tb_grow(v_lines) = tb_v14713; }
    { const char * tb_v14714 = "    double area = e1x * e2y - e1y * e2x;\n"; *(const char * *)tb_grow(v_lines) = tb_v14714; }
    { const char * tb_v14715 = "    if (fabs(area) < 0.5) return 0;   // смотрит на нас ребром: точек почти нет\n"; *(const char * *)tb_grow(v_lines) = tb_v14715; }
    { const char * tb_v14716 = "    double ia = 1 / area;\n"; *(const char * *)tb_grow(v_lines) = tb_v14716; }
    { const char * tb_v14717 = "    double ax = ((dd[1] - dd[0]) * e2y - (dd[2] - dd[0]) * e1y) * ia;\n"; *(const char * *)tb_grow(v_lines) = tb_v14717; }
    { const char * tb_v14718 = "    double by = ((dd[2] - dd[0]) * e1x - (dd[1] - dd[0]) * e2x) * ia;\n"; *(const char * *)tb_grow(v_lines) = tb_v14718; }
    { const char * tb_v14719 = "    if (ax > 1e9) ax = 1e9;\n"; *(const char * *)tb_grow(v_lines) = tb_v14719; }
    { const char * tb_v14720 = "    if (ax < -1e9) ax = -1e9;\n"; *(const char * *)tb_grow(v_lines) = tb_v14720; }
    { const char * tb_v14721 = "    if (by > 1e9) by = 1e9;\n"; *(const char * *)tb_grow(v_lines) = tb_v14721; }
    { const char * tb_v14722 = "    if (by < -1e9) by = -1e9;\n"; *(const char * *)tb_grow(v_lines) = tb_v14722; }
    { const char * tb_v14723 = "    double c0 = dd[0] - ax * sx[0] - by * sy[0];\n"; *(const char * *)tb_grow(v_lines) = tb_v14723; }
    { const char * tb_v14724 = "    // в целые: точка берётся по центру (2x + 1) / 2, поэтому ax / 2; ещё × 64 для точности\n"; *(const char * *)tb_grow(v_lines) = tb_v14724; }
    { const char * tb_v14725 = "    pl[0] = (uint32_t)tb_rnd(ax * 32); pl[1] = (uint32_t)tb_rnd(by * 32); pl[2] = (uint32_t)tb_rnd(c0 * 64);\n"; *(const char * *)tb_grow(v_lines) = tb_v14725; }
    { const char * tb_v14726 = "    return 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14726; }
    { const char * tb_v14727 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14727; }
    { const char * tb_v14728 = "// углы сетки после камеры: место перед камерой и на экране (округлённое), глубина D\n"; *(const char * *)tb_grow(v_lines) = tb_v14728; }
    { const char * tb_v14729 = "typedef struct { double cx, cy, cz, sx, sy, dd; long long rx, ry; int front, near_ok; } tb_3v;\n"; *(const char * *)tb_grow(v_lines) = tb_v14729; }
