    { const char * tb_v14924 = "// от камеры, всегда закрыта другими гранями — и у куба снаружи, и у комнаты изнутри (грани внутрь).\n"; *(const char * *)tb_grow(v_lines) = tb_v14924; }
    { const char * tb_v14925 = "// Повёрнута от камеры = на экране по часовой стрелке (площадь < 0). 0 — рисовать все, -1 — пропускать такие\n"; *(const char * *)tb_grow(v_lines) = tb_v14925; }
