    { const char * tb_v16722 = "        p->a[TB_PA_LX] = st.pad.lx / 32767.0; p->a[TB_PA_LY] = -st.pad.ly / 32767.0;\n"; *(const char * *)tb_grow(v_lines) = tb_v16722; }
