    { const char * tb_v16764 = "                case 6: p->b[TB_PB_LEFT] = e.value < -8000; p->b[TB_PB_RIGHT] = e.value > 8000; break;\n"; *(const char * *)tb_grow(v_lines) = tb_v16764; }
