    { const char * tb_v16814 = "    char *got = tb_gfx_clip_get();   // malloc или 0\n"; *(const char * *)tb_grow(v_lines) = tb_v16814; }
    { const char * tb_v16815 = "    size_t n = got ? strlen(got) : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v16815; }
    { const char * tb_v16816 = "    char *s = tb_tmem(n + 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v16816; }
