    { const char * tb_v16823 = "// вид стрелки мыши над окном\n"; *(const char * *)tb_grow(v_lines) = tb_v16823; }
    { const char * tb_v16824 = "TB_API void tb_set_cursor(const char *name, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16824; }
    { const char * tb_v16825 = "    static const char *names[] = { \"arrow\", \"hand\", \"text\", \"move\", \"resize_x\", \"resize_y\", \"wait\", \"none\" };\n"; *(const char * *)tb_grow(v_lines) = tb_v16825; }
    { const char * tb_v16826 = "    for (int i = 0; i < 8; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v16826; }
    { const char * tb_v16827 = "        if (strcmp(name, names[i]) == 0) { tb_cursor_prog = i; if (tb_px) { if (!tb_mlock) tb_gfx_cursor(i); } else tb_cursor_want = i; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v16827; }
    { const char * tb_v16828 = "    char buf[200];\n"; *(const char * *)tb_grow(v_lines) = tb_v16828; }
