    { const char * tb_v16830 = "    tb_crash(line, buf);\n"; *(const char * *)tb_grow(v_lines) = tb_v16830; }
    { const char * tb_v16831 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v16831; }
    { const char * tb_v16832 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v16832; }
    { const char * tb_v16833 = "// ---------- для файла .ll (TB_LL): библиотека видна снаружи через tb_x_* ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v16833; }
    { const char * tb_v16834 = "// Сама библиотека — static: так её лучше встраивать. Эти обёртки — её «дверь» для LLVM.\n"; *(const char * *)tb_grow(v_lines) = tb_v16834; }
    { const char * tb_v16835 = "// Без clang (llvm-link + opt + llc) библиотека заранее лежит в файле .bc, а программа\n"; *(const char * *)tb_grow(v_lines) = tb_v16835; }
    { const char * tb_v16836 = "// целиком в .ll: показ значений, конструкторы и main тоже пишутся в .ll.\n"; *(const char * *)tb_grow(v_lines) = tb_v16836; }
    { const char * tb_v16837 = "#if defined(TB_SND) && !defined(TB_BARE)\n"; *(const char * *)tb_grow(v_lines) = tb_v16837; }
    { const char * tb_v16838 = "// ---------- звук: load_sound, play_sound, play_sound_at, listener ... ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v16838; }
    { const char * tb_v16839 = "// Микшер: 48 000 кадров в секунду, стерео, числа float, блоки по 10 мс.\n"; *(const char * *)tb_grow(v_lines) = tb_v16839; }
    { const char * tb_v16840 = "// Голос = звук + громкость + высота (+ место в мире для 3D). В 3D: громкость падает с\n"; *(const char * *)tb_grow(v_lines) = tb_v16840; }
    { const char * tb_v16841 = "// расстоянием, сторона (лево/право) слышна по громкости И по задержке между ушами (как у\n"; *(const char * *)tb_grow(v_lines) = tb_v16841; }
    { const char * tb_v16842 = "// настоящей головы), дальнее ухо и звук сзади глуше (тень головы), воздух глушит высокие\n"; *(const char * *)tb_grow(v_lines) = tb_v16842; }
    { const char * tb_v16843 = "// у далёких звуков, а движение даёт эффект Доплера. Громкость и место меняются плавно\n"; *(const char * *)tb_grow(v_lines) = tb_v16843; }
    { const char * tb_v16844 = "// внутри блока — без щелчков. На выходе ограничитель: сколько звуков ни играй, не трещит.\n"; *(const char * *)tb_grow(v_lines) = tb_v16844; }
    { const char * tb_v16845 = "// Куда идёт звук: Mac — AudioQueue, Linux — ALSA, Windows — waveOut (библиотеки грузятся при\n"; *(const char * *)tb_grow(v_lines) = tb_v16845; }
    { const char * tb_v16846 = "// запуске; нет их — тишина, программа работает). TB_SOUND_FILE=путь.wav — в файл (проверки),\n"; *(const char * *)tb_grow(v_lines) = tb_v16846; }
    { const char * tb_v16847 = "// TB_SOUND=0 — никуда (время идёт, звуки «играют» молча).\n"; *(const char * *)tb_grow(v_lines) = tb_v16847; }
    { const char * tb_v16848 = "#ifndef _WIN32\n"; *(const char * *)tb_grow(v_lines) = tb_v16848; }
    { const char * tb_v16849 = "#include <dlfcn.h>\n"; *(const char * *)tb_grow(v_lines) = tb_v16849; }
    { const char * tb_v16850 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v16850; }
    { const char * tb_v16851 = "#define TB_SR 48000\n"; *(const char * *)tb_grow(v_lines) = tb_v16851; }
    { const char * tb_v16852 = "#define TB_SBLOCK 480\n"; *(const char * *)tb_grow(v_lines) = tb_v16852; }
    { const char * tb_v16853 = "#define TB_NVOICE 64\n"; *(const char * *)tb_grow(v_lines) = tb_v16853; }
    { const char * tb_v16854 = "typedef struct { float *d; long long n; int ch; double rate; int temp; } tb_snd;\n"; *(const char * *)tb_grow(v_lines) = tb_v16854; }
    { const char * tb_v16855 = "typedef struct {\n"; *(const char * *)tb_grow(v_lines) = tb_v16855; }
    { const char * tb_v16856 = "    int on, gen, snd, loop, is3d, fresh, stop;\n"; *(const char * *)tb_grow(v_lines) = tb_v16856; }
    { const char * tb_v16857 = "    double pos, pitch, vol, x, y, z;\n"; *(const char * *)tb_grow(v_lines) = tb_v16857; }
    { const char * tb_v16858 = "    float gl, gr, lpl, lpr;\n"; *(const char * *)tb_grow(v_lines) = tb_v16858; }
    { const char * tb_v16859 = "    double dl, dr, lastd, dop;\n"; *(const char * *)tb_grow(v_lines) = tb_v16859; }
    { const char * tb_v16860 = "} tb_voice;\n"; *(const char * *)tb_grow(v_lines) = tb_v16860; }
    { const char * tb_v16861 = "static tb_snd *tb_snds;\n"; *(const char * *)tb_grow(v_lines) = tb_v16861; }
    { const char * tb_v16862 = "static int tb_nsnd;\n"; *(const char * *)tb_grow(v_lines) = tb_v16862; }
    { const char * tb_v16863 = "static tb_voice tb_voices[TB_NVOICE];\n"; *(const char * *)tb_grow(v_lines) = tb_v16863; }
    { const char * tb_v16864 = "static pthread_mutex_t tb_slock = PTHREAD_MUTEX_INITIALIZER;\n"; *(const char * *)tb_grow(v_lines) = tb_v16864; }
    { const char * tb_v16865 = "// слушатель: где он, вектор «вправо», вектор «вперёд» (как у camera)\n"; *(const char * *)tb_grow(v_lines) = tb_v16865; }
    { const char * tb_v16866 = "static double tb_lis[9] = { 0, 0, 0, 1, 0, 0, 0, 0, 1 };\n"; *(const char * *)tb_grow(v_lines) = tb_v16866; }
    { const char * tb_v16867 = "static double tb_master = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v16867; }
    { const char * tb_v16868 = "static float tb_mg = 1, tb_lim = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v16868; }
    { const char * tb_v16869 = "static int tb_snd_started;\n"; *(const char * *)tb_grow(v_lines) = tb_v16869; }
    { const char * tb_v16870 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v16870; }
    { const char * tb_v16871 = "TB_INL float tb_sget(const tb_snd *s, long long i, int c, int loop) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16871; }
    { const char * tb_v16872 = "    if (i < 0 || i >= s->n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16872; }
    { const char * tb_v16873 = "        if (!loop || s->n == 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v16873; }
    { const char * tb_v16874 = "        i %= s->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v16874; }
    { const char * tb_v16875 = "        if (i < 0) i += s->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v16875; }
    { const char * tb_v16876 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v16876; }
    { const char * tb_v16877 = "    return s->d[i * s->ch + (c < s->ch ? c : 0)];\n"; *(const char * *)tb_grow(v_lines) = tb_v16877; }
    { const char * tb_v16878 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v16878; }
    { const char * tb_v16879 = "// точка между кадрами звука: кривая Эрмита по 4 соседям (чище, чем прямая между двумя)\n"; *(const char * *)tb_grow(v_lines) = tb_v16879; }
    { const char * tb_v16880 = "TB_INL float tb_sread(const tb_snd *s, double p, int c, int loop) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16880; }
    { const char * tb_v16881 = "    double fl = floor(p);\n"; *(const char * *)tb_grow(v_lines) = tb_v16881; }
    { const char * tb_v16882 = "    long long i = (long long)fl;\n"; *(const char * *)tb_grow(v_lines) = tb_v16882; }
    { const char * tb_v16883 = "    float t = (float)(p - fl);\n"; *(const char * *)tb_grow(v_lines) = tb_v16883; }
    { const char * tb_v16884 = "    float a = tb_sget(s, i - 1, c, loop), b = tb_sget(s, i, c, loop), cc = tb_sget(s, i + 1, c, loop), d = tb_sget(s, i + 2, c, loop);\n"; *(const char * *)tb_grow(v_lines) = tb_v16884; }
    { const char * tb_v16885 = "    float c1 = 0.5f * (cc - a), c2 = a - 2.5f * b + 2 * cc - 0.5f * d, c3 = 0.5f * (d - a) + 1.5f * (b - cc);\n"; *(const char * *)tb_grow(v_lines) = tb_v16885; }
    { const char * tb_v16886 = "    return ((c3 * t + c2) * t + c1) * t + b;\n"; *(const char * *)tb_grow(v_lines) = tb_v16886; }
    { const char * tb_v16887 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v16887; }
    { const char * tb_v16888 = "TB_INL float tb_smono(const tb_snd *s, double p, int loop) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16888; }
    { const char * tb_v16889 = "    if (s->ch > 1) return 0.5f * (tb_sread(s, p, 0, loop) + tb_sread(s, p, 1, loop));\n"; *(const char * *)tb_grow(v_lines) = tb_v16889; }
    { const char * tb_v16890 = "    return tb_sread(s, p, 0, loop);\n"; *(const char * *)tb_grow(v_lines) = tb_v16890; }
    { const char * tb_v16891 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v16891; }
    { const char * tb_v16892 = "// голос кончился: временный звук (play_tone) больше не нужен\n"; *(const char * *)tb_grow(v_lines) = tb_v16892; }
    { const char * tb_v16893 = "static void tb_voice_end(tb_voice *v) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16893; }
    { const char * tb_v16894 = "    v->on = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v16894; }
    { const char * tb_v16895 = "    tb_snd *s = &tb_snds[v->snd];\n"; *(const char * *)tb_grow(v_lines) = tb_v16895; }
    { const char * tb_v16896 = "    if (s->temp && s->d) { free(s->d); s->d = 0; s->n = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v16896; }
    { const char * tb_v16897 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v16897; }
    { const char * tb_v16898 = "// куда и как громко слышен 3D-голос: громкость ушей, задержка ушей, фильтры, Доплер\n"; *(const char * *)tb_grow(v_lines) = tb_v16898; }
    { const char * tb_v16899 = "static void tb_voice_3d(tb_voice *v, float *tl, float *tr, double *tdl, double *tdr, float *fl, float *fr) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16899; }
    { const char * tb_v16900 = "    double dx = v->x - tb_lis[0], dy = v->y - tb_lis[1], dz = v->z - tb_lis[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v16900; }
    { const char * tb_v16901 = "    double d = sqrt(dx * dx + dy * dy + dz * dz);\n"; *(const char * *)tb_grow(v_lines) = tb_v16901; }
    { const char * tb_v16902 = "    double side = 0, front = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v16902; }
    { const char * tb_v16903 = "    if (d > 1e-9) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16903; }
    { const char * tb_v16904 = "        side = (dx * tb_lis[3] + dy * tb_lis[4] + dz * tb_lis[5]) / d;\n"; *(const char * *)tb_grow(v_lines) = tb_v16904; }
    { const char * tb_v16905 = "        front = (dx * tb_lis[6] + dy * tb_lis[7] + dz * tb_lis[8]) / d;\n"; *(const char * *)tb_grow(v_lines) = tb_v16905; }
    { const char * tb_v16906 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v16906; }
    { const char * tb_v16907 = "    if (d < 0.25) { side *= d / 0.25; front = 1; }   // звук «в голове» — по центру\n"; *(const char * *)tb_grow(v_lines) = tb_v16907; }
    { const char * tb_v16908 = "    double g = d <= 1 ? 1 : 1 / d;                    // громкость падает с расстоянием\n"; *(const char * *)tb_grow(v_lines) = tb_v16908; }
    { const char * tb_v16909 = "    double a = (side + 1) * 0.7853981633974483;      // стороны с равной мощностью\n"; *(const char * *)tb_grow(v_lines) = tb_v16909; }
    { const char * tb_v16910 = "    *tl = (float)(v->vol * g * cos(a) * 1.4142135623730951);\n"; *(const char * *)tb_grow(v_lines) = tb_v16910; }
    { const char * tb_v16911 = "    *tr = (float)(v->vol * g * sin(a) * 1.4142135623730951);\n"; *(const char * *)tb_grow(v_lines) = tb_v16911; }
    { const char * tb_v16912 = "    double itd = 0.00066 * TB_SR * fabs(side);        // до 0,66 мс между ушами\n"; *(const char * *)tb_grow(v_lines) = tb_v16912; }
    { const char * tb_v16913 = "    *tdl = side > 0 ? itd : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v16913; }
    { const char * tb_v16914 = "    *tdr = side < 0 ? itd : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v16914; }
    { const char * tb_v16915 = "    double fc = 20000 / (1 + d * 0.03);               // воздух: далёкие звуки глуше\n"; *(const char * *)tb_grow(v_lines) = tb_v16915; }
    { const char * tb_v16916 = "    if (front < 0) fc *= 1 - 0.35 * -front;           // сзади глуше\n"; *(const char * *)tb_grow(v_lines) = tb_v16916; }
    { const char * tb_v16917 = "    double fs = fc * (1 - 0.65 * fabs(side));         // дальнее ухо в тени головы\n"; *(const char * *)tb_grow(v_lines) = tb_v16917; }
    { const char * tb_v16918 = "    double cl = side > 0 ? fs : fc, cr = side < 0 ? fs : fc;\n"; *(const char * *)tb_grow(v_lines) = tb_v16918; }
    { const char * tb_v16919 = "    *fl = (float)(1 - exp(-6.283185307179586 * cl / TB_SR));\n"; *(const char * *)tb_grow(v_lines) = tb_v16919; }
    { const char * tb_v16920 = "    *fr = (float)(1 - exp(-6.283185307179586 * cr / TB_SR));\n"; *(const char * *)tb_grow(v_lines) = tb_v16920; }
    { const char * tb_v16921 = "    // Доплер: как быстро звук приближается (расстояние за блок 10 мс), звук летит 343 ед/с\n"; *(const char * *)tb_grow(v_lines) = tb_v16921; }
    { const char * tb_v16922 = "    double want = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v16922; }
    { const char * tb_v16923 = "    if (!v->fresh) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16923; }
    { const char * tb_v16924 = "        double sp = (d - v->lastd) * TB_SR / TB_SBLOCK;\n"; *(const char * *)tb_grow(v_lines) = tb_v16924; }
    { const char * tb_v16925 = "        if (fabs(sp) < 686) want = 343 / (343 + sp);   // быстрее — это прыжок, не движение\n"; *(const char * *)tb_grow(v_lines) = tb_v16925; }
    { const char * tb_v16926 = "        if (want < 0.5) want = 0.5;\n"; *(const char * *)tb_grow(v_lines) = tb_v16926; }
    { const char * tb_v16927 = "        if (want > 2) want = 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v16927; }
    { const char * tb_v16928 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v16928; }
    { const char * tb_v16929 = "    v->dop = v->fresh ? 1 : v->dop * 0.8 + want * 0.2;\n"; *(const char * *)tb_grow(v_lines) = tb_v16929; }
    { const char * tb_v16930 = "    v->lastd = d;\n"; *(const char * *)tb_grow(v_lines) = tb_v16930; }
    { const char * tb_v16931 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v16931; }
    { const char * tb_v16932 = "// смешать n кадров всех голосов в out (стерео, по очереди лево-право)\n"; *(const char * *)tb_grow(v_lines) = tb_v16932; }
    { const char * tb_v16933 = "static void tb_mix(float *out, int n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16933; }
    { const char * tb_v16934 = "    memset(out, 0, sizeof(float) * 2 * (size_t)n);\n"; *(const char * *)tb_grow(v_lines) = tb_v16934; }
    { const char * tb_v16935 = "    pthread_mutex_lock(&tb_slock);\n"; *(const char * *)tb_grow(v_lines) = tb_v16935; }
    { const char * tb_v16936 = "    for (int k = 0; k < TB_NVOICE; k++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16936; }
    { const char * tb_v16937 = "        tb_voice *v = &tb_voices[k];\n"; *(const char * *)tb_grow(v_lines) = tb_v16937; }
    { const char * tb_v16938 = "        if (!v->on) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v16938; }
    { const char * tb_v16939 = "        tb_snd *s = &tb_snds[v->snd];\n"; *(const char * *)tb_grow(v_lines) = tb_v16939; }
    { const char * tb_v16940 = "        if (!s->d || s->n == 0) { tb_voice_end(v); continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v16940; }
    { const char * tb_v16941 = "        float tl = (float)v->vol, tr = (float)v->vol, al = 1, ar = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v16941; }
    { const char * tb_v16942 = "        double tdl = 0, tdr = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v16942; }
