    { const char * tb_v17174 = "// WAV: PCM 8/16/24/32 бита или float 32; моно или стерео (больше каналов — берём первые два)\n"; *(const char * *)tb_grow(v_lines) = tb_v17174; }
    { const char * tb_v17175 = "TB_API long long tb_load_sound(const char *path) {\n"; *(const char * *)tb_grow(v_lines) = tb_v17175; }
    { const char * tb_v17176 = "    FILE *f = fopen(path, \"rb\");\n"; *(const char * *)tb_grow(v_lines) = tb_v17176; }
    { const char * tb_v17177 = "    if (!f) { tb_err = \"нет такого файла звука\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v17177; }
    { const char * tb_v17178 = "    fseek(f, 0, SEEK_END); long sz = ftell(f); fseek(f, 0, SEEK_SET);\n"; *(const char * *)tb_grow(v_lines) = tb_v17178; }
    { const char * tb_v17179 = "    unsigned char *b = sz > 0 ? malloc((size_t)sz) : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v17179; }
    { const char * tb_v17180 = "    if (!b || fread(b, 1, (size_t)sz, f) != (size_t)sz) { fclose(f); free(b); tb_err = \"не могу прочитать файл звука\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v17180; }
    { const char * tb_v17181 = "    fclose(f);\n"; *(const char * *)tb_grow(v_lines) = tb_v17181; }
    { const char * tb_v17182 = "    if (sz < 12 || memcmp(b, \"RIFF\", 4) != 0 || memcmp(b + 8, \"WAVE\", 4) != 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v17182; }
    { const char * tb_v17183 = "        tb_err = sz >= 4 && memcmp(b, \"OggS\", 4) == 0 ? \"OGG пока не умею: сохрани звук как WAV\" : \"это не WAV-файл\";\n"; *(const char * *)tb_grow(v_lines) = tb_v17183; }
    { const char * tb_v17184 = "        free(b);\n"; *(const char * *)tb_grow(v_lines) = tb_v17184; }
    { const char * tb_v17185 = "        return -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v17185; }
    { const char * tb_v17186 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v17186; }
    { const char * tb_v17187 = "    uint32_t tag = 0, ch = 0, rate = 0, bits = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v17187; }
    { const char * tb_v17188 = "    const unsigned char *data = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v17188; }
    { const char * tb_v17189 = "    uint32_t dlen = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v17189; }
    { const char * tb_v17190 = "    long p = 12;\n"; *(const char * *)tb_grow(v_lines) = tb_v17190; }
    { const char * tb_v17191 = "    while (p + 8 <= sz) {\n"; *(const char * *)tb_grow(v_lines) = tb_v17191; }
    { const char * tb_v17192 = "        uint32_t n = tb_le32(b + p + 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v17192; }
    { const char * tb_v17193 = "        const unsigned char *c = b + p + 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v17193; }
    { const char * tb_v17194 = "        if ((long)n > sz - p - 8) n = (uint32_t)(sz - p - 8);   // последний кусок обрезан — берём что есть\n"; *(const char * *)tb_grow(v_lines) = tb_v17194; }
    { const char * tb_v17195 = "        if (memcmp(b + p, \"fmt \", 4) == 0 && n >= 16) {\n"; *(const char * *)tb_grow(v_lines) = tb_v17195; }
    { const char * tb_v17196 = "            tag = tb_le16(c); ch = tb_le16(c + 2); rate = tb_le32(c + 4); bits = tb_le16(c + 14);\n"; *(const char * *)tb_grow(v_lines) = tb_v17196; }
    { const char * tb_v17197 = "            if (tag == 0xFFFE && n >= 26) tag = tb_le16(c + 24);   // «расширенный» WAV: вид внутри\n"; *(const char * *)tb_grow(v_lines) = tb_v17197; }
    { const char * tb_v17198 = "        } else if (memcmp(b + p, \"data\", 4) == 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v17198; }
    { const char * tb_v17199 = "            data = c; dlen = n;\n"; *(const char * *)tb_grow(v_lines) = tb_v17199; }
    { const char * tb_v17200 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v17200; }
    { const char * tb_v17201 = "        p += 8 + (long)n + (n & 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v17201; }
    { const char * tb_v17202 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v17202; }
    { const char * tb_v17203 = "    int okf = (tag == 1 && (bits == 8 || bits == 16 || bits == 24 || bits == 32)) || (tag == 3 && (bits == 32 || bits == 64));\n"; *(const char * *)tb_grow(v_lines) = tb_v17203; }
    { const char * tb_v17204 = "    if (!data || !okf || ch == 0 || rate == 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v17204; }
    { const char * tb_v17205 = "        free(b);\n"; *(const char * *)tb_grow(v_lines) = tb_v17205; }
    { const char * tb_v17206 = "        tb_err = !data ? \"в WAV нет звука (нет куска data)\" : \"такой WAV не умею: нужен PCM 8/16/24/32 бита или float\";\n"; *(const char * *)tb_grow(v_lines) = tb_v17206; }
    { const char * tb_v17207 = "        return -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v17207; }
    { const char * tb_v17208 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v17208; }
    { const char * tb_v17209 = "    uint32_t bpf = ch * (bits / 8);\n"; *(const char * *)tb_grow(v_lines) = tb_v17209; }
    { const char * tb_v17210 = "    long long frames = dlen / bpf;\n"; *(const char * *)tb_grow(v_lines) = tb_v17210; }
    { const char * tb_v17211 = "    int oc = ch >= 2 ? 2 : 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v17211; }
    { const char * tb_v17212 = "    float *d = malloc(sizeof(float) * (size_t)(frames * oc + 1));\n"; *(const char * *)tb_grow(v_lines) = tb_v17212; }
    { const char * tb_v17213 = "    if (!d) { free(b); tb_err = \"не хватило памяти\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v17213; }
    { const char * tb_v17214 = "    for (long long i = 0; i < frames; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v17214; }
    { const char * tb_v17215 = "        for (int k = 0; k < oc; k++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v17215; }
    { const char * tb_v17216 = "            const unsigned char *q = data + i * bpf + (uint32_t)k * (bits / 8);\n"; *(const char * *)tb_grow(v_lines) = tb_v17216; }
    { const char * tb_v17217 = "            float v;\n"; *(const char * *)tb_grow(v_lines) = tb_v17217; }
    { const char * tb_v17218 = "            if (tag == 3) {\n"; *(const char * *)tb_grow(v_lines) = tb_v17218; }
