    { const char * tb_v17254 = "    v->pitch = 1; v->vol = 1; v->x = x; v->y = y; v->z = z; v->dop = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v17254; }
    { const char * tb_v17255 = "    long long id = (long long)gen * TB_NVOICE + k + 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v17255; }
