    { const char * tb_v17270 = "// тон: синус hz герц на ms миллисекунд, мягкое начало и конец (без щелчков)\n"; *(const char * *)tb_grow(v_lines) = tb_v17270; }
    { const char * tb_v17271 = "TB_API long long tb_play_tone(double hz, long long ms) {\n"; *(const char * *)tb_grow(v_lines) = tb_v17271; }
    { const char * tb_v17272 = "    if (ms <= 0 || hz <= 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v17272; }
    { const char * tb_v17273 = "    if (ms > 60000) ms = 60000;\n"; *(const char * *)tb_grow(v_lines) = tb_v17273; }
    { const char * tb_v17274 = "    long long n = ms * TB_SR / 1000;\n"; *(const char * *)tb_grow(v_lines) = tb_v17274; }
    { const char * tb_v17275 = "    float *d = malloc(sizeof(float) * (size_t)(n + 1));\n"; *(const char * *)tb_grow(v_lines) = tb_v17275; }
    { const char * tb_v17276 = "    if (!d) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v17276; }
    { const char * tb_v17277 = "    long long ramp = TB_SR / 200;\n"; *(const char * *)tb_grow(v_lines) = tb_v17277; }
    { const char * tb_v17278 = "    if (ramp * 2 > n) ramp = n / 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v17278; }
    { const char * tb_v17279 = "    for (long long i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v17279; }
    { const char * tb_v17280 = "        double e = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v17280; }
    { const char * tb_v17281 = "        if (i < ramp) e = (double)i / ramp;\n"; *(const char * *)tb_grow(v_lines) = tb_v17281; }
    { const char * tb_v17282 = "        else if (i >= n - ramp) e = (double)(n - 1 - i) / ramp;\n"; *(const char * *)tb_grow(v_lines) = tb_v17282; }
    { const char * tb_v17283 = "        d[i] = (float)(0.5 * e * sin(6.283185307179586 * hz * (double)i / TB_SR));\n"; *(const char * *)tb_grow(v_lines) = tb_v17283; }
    { const char * tb_v17284 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v17284; }
    { const char * tb_v17285 = "    long long s = tb_snd_add(d, n, 1, TB_SR, 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v17285; }
